INSERT INTO vi_metric_base (id, code, name, unit, category, source_name, frequency, valid_min, valid_max, notes, company_id) VALUES
(1, '600900.SH.PRICE', '长江电力收盘价', '元', '行情', '腾讯行情（自动采集）；Wind（2026-09 备份 1 条）', '交易日', 0, 1000, '股价只进入对比层，不进入经营假设。', NULL),
