INSERT INTO vi_company_base (id, code, name, exchange, industry, currency, volume_label, volume_unit, price_label, price_unit, is_default, profile, notes, price_metric_id, price_fx_metric_id, scope_breaks) VALUES
(1, '600900.SH', '长江电力', '上海证券交易所', '水电', '人民币', '发电量（境内六座梯级电站）', '亿千瓦时', '综合电价（营业收入÷发电量）', '元/千瓦时', TRUE, '长江干流六座梯级电站（乌东德、白鹤滩、溪洛渡、向家坝、三峡、葛洲坝），装机 7179.5 万千瓦，全球最大水电。资产不可复制，大坝寿命以百年计，经营近乎永续。收入＝发电量×电价，两者都长期可测：来水围绕均值波动、六库联调平滑；电价以管制为主。成本大头是折旧（非现金）和财务费用（随还债退坡）。2026—2030 年承诺每年现金分红不低于归母净利润的 70%。本质类似“永续债＋温和递增票息”。', '主要风险：极端枯水、电价市场化折价、低回报资本配置（抽蓄约 800 万千瓦在建、葛洲坝扩能约 266 亿）、利率上行。', 1, NULL, '2016、2023');
INSERT INTO vi_source_base (id, title, source_type, publisher, publish_date, url, reliability, verify_status, retrieved_on, summary, limitations, company_id) VALUES
(1, '长江电力 2025 年年度报告', '定期报告', '长江电力', '2026-04-30', 'http://file.finance.sina.com.cn/211.154.219.97:9494/MRGG/CNSESH_STOCK/2026/2026-4/2026-04-30/12283277.PDF', '一级·法定披露', '待核验', '2026-09-01', '营业收入 862.42 亿元（+2.07%）；归母净利润 345.03 亿元（+6.17%）；六站发电量 3071.94 亿千瓦时首破 3000 亿；每 10 股派 10 元，派息率 70.92%；折旧 195.29 亿元；财务费用 93.71 亿元（−17.60 亿）。', '历史数值尚未逐项与原页勾稽（问题清单 Q03）。', 1),
(2, '长江电力 2026 年半年度报告', '定期报告', '长江电力', '2026-08-30', 'https://vip.stock.finance.sina.com.cn/corp/go.php/vCB_AllBulletin/stockid/600900.phtml', '一级·法定披露', '待核验', '2026-09-01', '营收 379.29 亿元（+3.36%）；归母净利 147.56 亿元（+13.02%）；六站发电量 1327.44 亿千瓦时（+4.81%）创同期新高；财务费用 42.01 亿元（−13.61%）；三峡来水偏丰 28.7% 对冲金沙江偏枯。', '链接为公告列表入口。', 1),
(3, '未来五年（2026—2030 年）股东分红回报规划', '临时公告', '长江电力', '2025-08-14', 'https://www.cypc.com.cn/eportal/attachDir/cypc/2025/09/2025090114575095227.pdf', '一级·法定披露', '已读原文', '2026-09-01', '每年现金分红不低于当年归母净利润的 70%，优先现金分红，写入公司章程。', NULL, 1),
(4, '2024 年发电量完成情况公告', '临时公告', '长江电力', '2025-01-08', 'https://static.sse.com.cn/disclosure/listedinfo/announcement/c/new/2025-01-08/600900_20250108_8R1Z.pdf', '一级·法定披露', '已读原文', '2026-09-01', '六站全年发电 2959.04 亿千瓦时（+7.11%）；乌东德来水偏丰 9.19%，三峡偏丰 9.11%；四季度丰枯急转，单季 −17.60%。', NULL, 1),
(5, '2025 年三季度发电量完成情况公告', '临时公告', '长江电力', '2025-10-12', NULL, '一级·法定披露', '已读原文', '2026-10-21', '前三季度六站发电 2351.26 亿千瓦时，与上年基本持平（−0.29%）；三季度单季 1084.70，−5.84%。乌东德来水偏枯 6.04%，三峡偏枯 4.54%。', '经岗底斯取得公告原文（file-id 12919717）。', 1),
(6, '2025 年发电量完成情况公告', '临时公告', '长江电力', '2026-01-05', NULL, '一级·法定披露', '已读原文', '2026-10-21', '2025 年六站发电 3071.94 亿千瓦时，+3.82%；四季度单季 720.68，+19.93%。乌东德来水偏枯 6.44%，三峡偏丰 5.93%。', '经岗底斯取得公告原文（file-id 13680781）。', 1),
(7, '2026 年第一季度发电量完成情况公告', '临时公告', '长江电力', '2026-04-09', NULL, '一级·法定披露', '已读原文', '2026-10-21', '一季度六站发电 618.25 亿千瓦时，+7.19%。乌东德来水偏枯 7.36%，三峡偏丰 5.49%。', '经岗底斯取得公告原文（file-id 22722231）。', 1),
(8, '2026 年三季度发电量完成情况公告', '临时公告', '长江电力', '2026-10-12', NULL, '一级·法定披露', '已读原文', '2026-10-21', '前三季度六站发电 2250.58 亿千瓦时，−4.28%；三季度单季 923.14，−14.89%（三峡单季 −29.23%）。乌东德来水偏枯 9.29%，三峡偏丰 0.98%。', '经岗底斯取得公告原文（file-id 96518947）。', 1),
(9, '控股股东增持计划实施完毕', '临时公告', '长江电力', '2026-08-25', 'https://vip.stock.finance.sina.com.cn/corp/go.php/vCB_AllBulletin/stockid/600900.phtml', '一级·法定披露', '待核验', '2026-09-01', '三峡集团累计增持 1.62 亿股、金额 44.99 亿元，超过计划下限。治理信号，不改变模型输入。', '链接为公告列表入口。', 1),
(10, '2026 年度中期票据及超短期融资券发行', '临时公告', '长江电力', '2026-07-08', 'https://vip.stock.finance.sina.com.cn/corp/go.php/vCB_AllBulletin/stockid/600900.phtml', '一级·法定披露', '待核验', '2026-09-01', '中票票面利率 2.05%/2.06%，超短融 1.32%/1.34%，存量债务成本持续压降。', '链接为公告列表入口。', 1),
(11, '公司官网·分红专栏', '官方网站', '长江电力', NULL, 'https://www.cypc.com.cn/cypc/tzzgx43/xxtm/glfpzcbh/index.html', '一级·法定披露', '仅定位入口', '2026-09-01', '历年分红方案。2014—2020 年归母净利润与分红总额来自此处整理。', NULL, 1),
(12, '公司官网·投资者关系', '官方网站', '长江电力', NULL, 'https://www.cypc.com.cn/cypc/tzzgx43/index.html', '一级·法定披露', '仅定位入口', '2026-09-01', '公告、定期报告、分红专栏入口。', NULL, 1),
(13, '新浪财经·600900 公告列表', '官方网站', '新浪财经', NULL, 'https://vip.stock.finance.sina.com.cn/corp/go.php/vCB_AllBulletin/stockid/600900.phtml', '三级·第三方数据', '仅定位入口', '2026-09-01', '历史公告 PDF 聚合入口，含历年年报。', '第三方聚合，以交易所原件为准。', 1),
(14, 'Wind：长江电力 2014—2025 年财务数据', '数据库取数', '万得', NULL, NULL, '三级·第三方数据', '数值已核对', '2026-10-21', '营业收入、归母净利、财务费用、投资收益、折旧摊销、经营现金流、资本开支、带息债务、每股股利。2021—2025 年与旧值逐项一致。', 'Wind 折旧不含使用权资产（比本表低约 1 亿/年）；每股股利只含年末分红；带息债务含租赁负债、不含其他流动负债，2024 年比旧值低 19.9 亿。', 1),
(15, 'Wind EDB：长江电力发电量累计值（S0069453）', '数据库取数', '万得', NULL, NULL, '三级·第三方数据', '数值已核对', '2026-10-21', '2014—2026Q3 发电量，来源为上市公司公告。2023—2025 年与公告一致。', '各年为当年并表口径，跨期不可直接同比。', 1),
(16, '岗底斯：长江电力 2023—2025 年三大报表', '数据库取数', '岗底斯', NULL, NULL, '三级·第三方数据', '数值已核对', '2026-10-21', '利润表、现金流量表、资产负债表（合并口径）。用于拆分税与少数股东、现金桥接和债务。', '维持与扩张资本开支公司未分开披露。', 1),
(17, '旧工作台年度数据（2026-09-01 建表）', '旧系统迁移', '本研究', '2026-09-01', NULL, '研究推导', '待核验', '2026-09-19', '2026-09 在飞书建表时从官网分红专栏、年报整理的历年归母净利润、分红与部分财务数据。', '原表来源不一定覆盖同一行全部指标；重组前后不直接同比。', 1),
(18, '伯克希尔·哈撒韦 1986 年致股东信', '研究方法', '巴菲特', '1987-02-27', 'https://www.berkshirehathaway.com/letters/1986.html', '研究推导', '已读原文', '2026-09-19', '所有者收益＝净利润＋折旧摊销等非现金费用−维持长期竞争地位与业务量所需的平均资本支出及必要营运资本。', NULL, NULL),
(19, '中国债券信息网', '官方网站', '中央国债登记结算有限责任公司', NULL, 'https://www.chinabond.com.cn', '二级·官方统计', '仅定位入口', '2026-09-01', '中债国债收益率曲线。', NULL, NULL),
(20, '长江水文网', '官方网站', '水利部长江水利委员会', NULL, 'http://www.cjh.com.cn/sqindex.html', '二级·官方统计', '仅定位入口', '2026-09-19', '水库水情日报（水位、出库流量）。三峡入库流量页面未提供。', '站点 HTTPS 未连通，使用 HTTP。', NULL),
(21, '上海证券交易所信息披露', '官方网站', '上交所', NULL, 'https://www.sse.com.cn', '一级·法定披露', '仅定位入口', '2026-09-01', '法定披露平台。', NULL, NULL),
(22, '国家发展改革委', '官方网站', '国家发改委', NULL, 'https://www.ndrc.gov.cn', '二级·官方统计', '仅定位入口', '2026-09-01', '电价与能源政策文件。', NULL, NULL),
(23, '研究推导：2026—2035 年现金桥接建议值', '研究推导', '本研究', '2026-10-21', NULL, '研究推导', '待核验', '2026-10-21', '以 2023—2025 年合并报表实际值为锚推导维持/扩张资本、净借款、投资分红等，详见判断 J-CB2026。', '判断成分高，需用户确认。', 1),
(927, '三峡水库入库流量（Wind）、三峡水库水位（Wind）、向家坝水库入库流量（Wind）：Wind / 长江水文网（2026 年历史数据）', '数据库取数', 'Wind / 长江水文网', NULL, NULL, '三级·第三方数据', '待核验', NULL, '18 条历史数据（2026-08-27 至 2026-09-17）', '观察数据；水文不得直接外推全年电量；国债为中证口径，非中债，不自动改长期折现率', 1),
(928, '长江电力收盘价：Wind 金融数据服务（2026 年历史数据）', '数据库取数', 'Wind 金融数据服务', NULL, NULL, '三级·第三方数据', '待核验', NULL, '1 条历史数据（2026-09-18 至 2026-09-18）', '独立市场观察；不得直接与2025年末条件估值作为现时买卖信号比较', 1);
INSERT INTO vi_fact_base (id, title, category, statement, period, as_of, verify_status, notes, company_id, source_id) VALUES
(1, '总股本 244.68 亿股', '治理', '2025 年末发行在外总股本 244.68 亿股，是每股价值的分母。', '2025', '2025-12-31', '待核验', NULL, 1, 1),
(2, '水电总装机 7179.5 万千瓦，境内六站 7169.5 万千瓦', '经营', '2025 年年报：水电总装机容量 7179.5 万千瓦，其中国内水电装机 7169.5 万千瓦，约占全国水电装机的 16%。发电量上限＝装机×利用小时，扩机增容（葛洲坝、向家坝、溪洛渡）才改变上限。（2026-10-23 更正：此前把 7179.5 万千瓦写成了境内六站装机。）', '2025', '2025-12-31', '已核验', NULL, 1, 1),
(3, '2026—2030 年分红承诺不低于 70%', '分红', '2026—2030 年每年现金分红不低于当年归母净利润的 70%，已写入公司章程。2021—2025 年实际派息率 70.6%、94.3%、73.7%、71.0%、70.9%。', '2026—2030', '2025-08-14', '已核验', NULL, 1, 3),
(4, '新发债务成本约 1.3%—2.1%', '债务', '2026 年 7 月中期票据票面 2.05%/2.06%，超短期融资券 1.32%/1.34%，低于存量成本，置换持续降费。', '2026', '2026-07-08', '待核验', NULL, 1, 10),
(5, '折旧政策：大坝 40—60 年、机电设备 5—32 年', '财务', '直线法计提；机组折旧到期后停止计提，利润释放但不等额增加所有者收益（仍需更新改造）。', '2025', '2025-12-31', '待核验', NULL, 1, 1),
(6, '2026 上半年来水：三峡偏丰 28.7%、金沙江偏枯', '水文', '六库联调平滑区域差异，2026H1 发电量创同期新高。', '2026H1', '2026-06-30', '待核验', NULL, 1, 2),
(7, '电价机制：葛洲坝成本加成、三峡落地倒推，金沙江四站倒推加市场化', '政策', '葛洲坝（1988 年全部投产）按成本加成定价；三峡首创落地倒推电价（落地价−输电价−线损），丰水期送广东、华东各 50%，枯水期广东 16%、华东 32%、华中 52%；溪洛渡（送浙江、广东）、向家坝（送上海）、乌东德（送广东、广西，留存云南按省内市场价）为倒推电价加市场化电价；白鹤滩（送江苏、浙江，留存四川 100 亿、云南 40 亿千瓦时）过渡期后全部市场化。三峡、葛洲坝不参与市场化交易；2021 年披露向家坝、溪洛渡市场化比例约 22%、26%。市场化电量占比 2023 年以前低于 15%，乌东德、白鹤滩注入后约 40%（2023 年 37.76%）。', '2023', '2023-12-31', '待核验', '市场化占比 37.76% 来自年报；各电站定价方式与消纳比例来自《长江电力价值手册 2022》（首创、开源转引）。', 1, 1),
(8, '在建投资：抽蓄约 800 万千瓦、葛洲坝扩能约 266 亿', '资本开支', '抽水蓄能：锁定资源近 4000 万千瓦，在建及推进约 800—900 万千瓦（甘肃张掖、湖南攸县、河南巩义、江西寻乌等），2028 年起陆续投产；两部制电价，容量电价按经营期定价法核定（资本金内部收益率 6.5%）；受托运维长龙山抽蓄（210 万千瓦）。2025 年完成河南巩义、江西寻乌 2 个项目投资决策和河北青龙等 4 个项目公司股权收购。葛洲坝航运扩能约 266 亿元（工期 91 个月，年均约 35 亿元）。', '2025', '2025-12-31', '待核验', '投资决策与收购来自 2025 年年报；资源规模、受托运维来自卖方与同业对比资料。', 1, 1),
(10, '所有者收益方法', '估值方法', '所有者收益须扣除维持长期竞争地位与业务量所需的平均资本支出及必要营运资本投入；折旧到期不代表现金凭空增加。', '方法', NULL, '已核验', NULL, 1, 18),
(11, '2025 年现金流补充项', '财务', '2025 年：折旧摊销 195.29 亿（固定资产 190.89＋使用权 1.14＋无形 3.05＋长摊 0.22）；营运资本释放 12.11 亿（2024 年 10.76 亿）；资产减值准备 15.05 亿（非经常）；子公司付少数股东股利 6.49 亿。', '2025', '2025-12-31', '已核验', NULL, 1, 16),
(12, '2026 年上半年经营要点', '经营', '营收 379.29 亿元（+3.36%）；归母净利 147.56 亿元（+13.02%）；发电量 1327.44 亿千瓦时（+4.81%）；财务费用 42.01 亿元（−13.61%）。', '2026H1', '2026-06-30', '待核验', NULL, 1, 2),
(13, '控股股东增持 44.99 亿元', '治理', '三峡集团累计增持 1.62 亿股、金额 44.99 亿元，超过计划下限。', '2026', '2026-08-25', '待核验', NULL, 1, 9),
(14, '2026 年前三季度发电量 −4.28%', '经营', '前三季度六站发电 2250.58 亿千瓦时，同比 −4.28%；三季度单季 −14.89%，三峡单季 −29.23%。全年模型电量 3100 亿千瓦时需结合四季度复核。', '2026Q1—Q3', '2026-09-30', '已核验', NULL, 1, 8);
INSERT INTO vi_judgment_base (id, code, title, fact_layer, judgment, transmission, parameter, affected_years, change_threshold, no_change_condition, counter_evidence, status, company_id) VALUES
(1, 'J-Q', '来水与发电量', '观察到来水/发电数据后才录入数值', '短期偏枯可能下调年度电量，不必永久化；悲观情景的业务量系数对应连续偏枯。', 'Δ收入=Δ售电量×不含税电价；经税、现金及折现传导', '逐年假设·业务量', '2026近端；结构变化才及远期', '公司季度电量或经回测的水文—发电关系；同口径累计比较；2026 年发电量在四季度复核。', '只有单日、单站流量异常，或已包含在假设内', '水头、库容与调度可抵消流量影响', '研究规则', 1),
(2, 'J-P', '实现电价', '合同结算或报告披露电价', '政策和交易结构改变平均实现价格；基准不假设电价上涨。', 'Δ收入=售电量×Δ实现电价', '逐年假设·单价', '合同生效期及各情景', '确认含税/不含税、地区、结算量和生效日期；若沿海年度长协继续下降，先在悲观情景下调单价系数，不机械改基准。', '只有政策标题或行业平均电价', '含税变动、售电结构、境外汇率及其他业务混合', '研究规则', 1),
(3, 'J-DA', '折旧退坡', '折旧政策及资产明细原件待核验', '旧模型折旧下降可能提升利润，但不等额增加现金', '净利+ΔD×(1-t)，加回折旧-ΔD；现金净效应约-ΔD×t，另计税务差异', '逐年假设·折旧', '2026—2035', '按资产类别折旧台账、税务及更新预算', '仅推测大坝寿命或设备账面折旧到期', '重新购置机组和大修支出上升；税务折旧不同', '研究规则', 1),
(4, 'J-DEBT', '债务与利息', '债务到期、利率、净融资与付息分类', '降息/去杠杆可降利息但偿债消耗现金', '利息=平均债务×有效利率；FCFE另加净借款', '逐年假设·净借款、平均债务成本', '逐年；利率冲击独立于经营情景', '财报债务附注与现金融资勾稽', '只看到国债利率下降', '新项目加杠杆、浮息重定价延迟', '已形成建议', 1),
(5, 'J-CAPEX', '维持与扩张资本', '维持性/扩张性资本项目及预算', '只认可增量回报超过资本成本的增长；扩张资本开支计入现金桥接，新项目收益没有计入收入假设（现金支持价值偏保守）。', 'FCFE扣全部资本开支；所有者收益扣维持资本；终值增长需再投资支持', '逐年假设·维持/扩张资本', '建设期现金流及投产后收益', '项目公告和支付进度，区分承诺额与当年现金支付', '只有规划装机，无预算与进度', '建设延期、超支、容量电价政策和关联交易', '已形成建议', 1),
(6, 'J-CASH', '归母现金桥接', '归母净利与合并CFO口径不同；要看被投资企业分红、少数股东利润及分红、母公司现金（2025 年的权益法收益与现金分红见商业模式 B9）。', '需非现金、权益法分红、少数股东等桥接', '归母利润+归属折旧-非现金收益+投资现金分红-Δ营运资本-资本开支+净借款', '逐年假设·非现金收益扣除、收到投资分红、少数股东占比', '所有年度', '逐项现金桥接；未知值留空，不能默认0', '只算CFO减资本开支', '营运资本释放与一次性回款不可永久化；用合并经营现金流估归母 FCFE 可能高估。', '已形成建议', 1),
(7, 'J-R', '要求回报率', '国债收益率观察值需日期与来源；中债 10 年收益率趋势、长期通胀与风险溢价。', '要求回报率由无风险参考、风险补偿与机会成本共同决定：折现率＝10 年国债＋3.5% 风险溢价。当前国债收益率处历史低位，利率上行是这类“类债资产”最大的估值风险；无风险利率取高频数据里的中债 10 年期国债到期收益率（建模时 1.69%，2026-08-31），加风险溢价后按 0.1 个百分点四舍五入（5.19% → 5.2%）。', 'r上升→现金折现下降；不改变经营现金流。r 每升 0.5 个百分点，基准价值约 −2.8 元（27.28 → 24.46 元，见敏感性表）。', '估值模型·无风险利率、风险溢价；情景·折现率', '估值全期限', '记录名义人民币口径与期限，独立做利率压力', '单日波动不自动覆盖长期要求回报；利率风险用敏感性表展示，不机械改长期折现率。', '低利率未必长期持续，风险溢价不能机械固定', '研究规则', 1),
(8, 'J-TV', '终值与永续增长', '终期盈利、资本更新与增长条件', '永续增长必须有留存与回报支撑；基准永续增长 1%：按稳定现金流建模。', '终值=规范化下一年分配/(r-g)；r必须大于g', '情景·永续增长率', '2036及以后', '更新资本、负债与分配可持续；同时报告终值占比', '仅以国债低利率或大坝寿命支持高终值', '资产寿命/气候/监管结构变化；终值占比高', '研究规则', 1),
(9, 'J-CB2026', '2026—2035 年现金桥接建议值', '2023—2025 年合并报表：资本开支 122/144/185 亿；净借款 +295（并购融资）/−152/−95 亿；收到投资分红 21.5/25.5/26.4 亿；权益法收益 42.3/43.6/46.2 亿；营运资本释放 92.9/10.8/12.1 亿。', '维持资本 55 亿起、年增 2%（四站时期 2017—2021 年均资本开支约 31 亿，按装机 7179.5/4549.5 放大约 49 亿，再计通胀与设备老化）；扩张资本 2026—2027 年 130 亿、2028 年 110、2029 年 90、2030 年 60、之后 30（2025 年资本开支 184.88 减维持约 55）；净借款 2026—2030 年 −120 亿/年、之后 −100（2024—2025 年均 −124）；非现金收益扣除 46、收到投资分红 26（2025 年实际）；其他现金调整 0（资产减值 15.05 为一次性）；营运资本增加 0（近两年的释放不外推）；最低现金补充 0（年末货币资金 45.86 亿，不额外留存）。', '所有者收益＝归母净利＋归属折旧−非现金收益＋投资分红＋其他调整−营运资本增加−维持资本；FCFE＝所有者收益−扩张资本＋净借款；现金支持股息＝min(计划股息, FCFE−最低现金补充)。', '逐年假设·现金桥接 7 项与净借款', '2026—2035，全部情景', '公司披露维持/扩张资本拆分、项目预算与支付进度、债务计划后替换。', '只有规划装机、没有预算与进度；或单季现金流波动。', '扩张项目投产后的新增收益没有进入收入假设，现金支持价值偏保守；若公司放慢还债，股息缺口可由借款弥补。', '已形成建议', 1);
