INSERT INTO vi_model_base (id, name, status, method, base_year, terminal_year, shares, rf, rf_date, erp, opening_debt, margin_low, margin_high, notes, company_id, rf_metric_id, required_return, opening_op_assets, opening_lt_invest, opening_equity, opening_minority, primary_method, sotp_year, sotp_core_adj, sotp_as_of) VALUES
(1, '长江电力 隐含回报（2025 年末基准）', '当前', '把每股股息当票息，求按市价买入的隐含年化回报，和门槛 6% 比；股东自由现金流只用来检查股息付不付得出。股价只进对比层。', 2025, 2035, 244.68, 0.0169, '2026-08-31', 0.035, 2907.51, 0.1, 0.3, '经营假设来自 2026-09-01 旧模型：业务量 2026 年 3100、此后 3050 亿千瓦时（2023—2025 年均 2931，六库联调缓升）；电价持平 2025 年 0.2807；付现成本 203 起年增约 1%；折旧 190 起，三峡机组到期年均降约 5 亿，2031—2032 年溪洛渡/向家坝到期加速，2035 年约 144；其他净贡献 45（2025 年校准）；派息率 72%（承诺下限 70%）。2026-10-21 重构：综合负担率 17.34% 拆为所得税率 16.27% 与少数股东占比 1.28%（2025 年实际）；利息改为债务滚动，平均债务成本按原利息路径反推（3.02%→2.05%，与新发债利率 1.3%—2.1% 方向一致，待核验）。2026-10-25 起估值只看按市价买入的隐含回报 vs 门槛（要求收益率 6%，依据 J-R），不用安全边际；无风险利率、风险溢价与情景折现率不参与结论。期初资产负债取 2025 年末合并资产负债表（岗底斯）：经营性长期资产 4581.84＝固定资产 4165.74＋在建工程 159.06＋无形资产 250.25＋使用权资产 6.79；长期股权投资 749.36；归母权益 2213.38；少数股东权益 120.23；带息负债 2907.51。', 1, 2, 0.06, 4581.84, 749.36, 2213.38, 120.23, NULL, NULL, NULL, NULL);
