(2, '基准', TRUE, 2, 1, 1, 1, NULL, 0.01, '旧模型迁移+研究者压力假设；非预测事实', '旧模型 10 年路径：发电量 2026 年 3100、此后 3050 亿千瓦时，电价持平 0.2807 元，永续增长 1%。', 1, NULL, NULL, NULL),
(3, '乐观', FALSE, 3, 1.05, 1.01, 1, NULL, 0.015, '旧模型迁移+研究者压力假设；非预测事实', '六库联调多发电、电价小幅上行：发电量 +5%、电价 +1%，永续增长 1.5%。', 1, NULL, NULL, NULL);
