INSERT INTO vi_trial_base (id, name, start_year, end_year, volume_delta, price_delta, cost_delta, da_delta, interest_delta, rate_delta, boundary, model_id) VALUES
(1, '来水压力→仅2026电量-10%', 2026, 2026, -0.1, 0, 0, 0, 0, 0, '压力测试；不是来水事实，也不是流量与电量的线性回归。', 1),
(2, '电价压力→全期电价-3%', 2026, 2035, 0, -0.03, 0, 0, 0, 0, '压力测试；只有合同/结算口径核实后才能转正式假设。', 1),
(3, '折旧减少10亿→2026利润与现金不同', 2026, 2026, 0, 0, 0, -10, 0, 0, '计划股息随利润增加；同税口径现金因税盾减少约1.734亿。综合负担率为代理，现金税需另核验。', 1),
(4, '融资降本→每年利息少10亿', 2026, 2035, 0, 0, 0, 0, -10, 0, '假设减少的是真实利息；若靠偿债实现，需另计净偿债现金，不是免费收益。', 1),
(5, '要求回报率提高50bp', 2026, 2035, 0, 0, 0, 0, 0, 0.005, '机会成本压力测试；不改变经营利润，仅改变折现。', 1);
INSERT INTO vi_issue_base (id, code, title, severity, impact, done_condition, status, progress, company_id) VALUES
(1, 'Q01', '安全边际手册30%与表内10%不一致', '策略', '关注价', '用户策略明确后记录政策版本', '已解决', '2026-10-25：估值改为隐含回报 vs 门槛 6%，不再使用安全边际（用户决定）。', 1),
(2, 'Q02', '六站发电量乘合并隐含电价可能混用口径', '关键', '收入', '核验售电量、含税、海外与其他收入桥接', '待处理', NULL, 1),
(3, 'Q03', '2025历史值尚未逐项与官网原件勾稽', '关键', '全模型', '年报、半年报原页与结构化数值一致', '处理中', '2014—2025 年数据已由 Wind/岗底斯补齐并与旧值交叉核对一致；仍需年报原页抽查。', 1),
(4, 'Q04', '折旧退坡缺资产级证据', '关键', '利润与现金', '按电站/资产类别核验；维护支出联动', '待处理', NULL, 1),
(5, 'Q05', '利息固定递减而无债务滚动', '关键', '利润与现金', '期初债务+净借款=期末债务；平均债务×成本', '处理中', '利息已改为债务滚动计算（期初负债＋净借款，平均负债×债务成本）。隐含债务成本 3.02%→2.05% 待核验。', 1),
(6, 'Q06', 'CFO减资本开支并非完整归母FCFE', '关键', '股息付不付得出的检查（现金支持口径的隐含回报）', '填完归属折旧、非现金收益、投资分红、营运资本、资本预算与净借款', '处理中', '现金桥接 9 项已填建议值（判断 J-CB2026），等待用户确认。', 1),
(7, 'Q07', '综合负担率混合税率和少数股东', '关键', '归母利润', '拆为所得税、少数股东损益及现金归属', '已解决', '已拆为所得税率 16.27% 与少数股东占比 1.28%（2025 年实际），归属折旧按少数股东占比自动计算。', 1),
(8, 'Q08', '价格日期2026-09-01；DDM基准2025年末', '关键', '现时投资信号', '核验最新价与除息，按实际估值日重置未来现金时点', '处理中', '股价改为自动采集的最新收盘价；隐含回报从今天起算现金流（已过去的部分不计）。分红时点仍按年末简化。', 1),
(9, 'Q09', '终值增长缺更新资本和再投资回报支撑', '关键', '终值', '规范化终期现金流，检验g与再投资及资本回报一致', '待处理', NULL, 1),
(10, 'D1', '数据源待接通：三峡入库流量', '数据源', '跟踪', '找到可自动采集且口径正确的来源，加入采集配置。', '待处理', '已抓官方页面未提供入库流量，不能用出库流量替代。Wind手动备份仍保留。', 1),
(11, 'D2', '数据源待接通：向家坝入库流量', '数据源', '跟踪', '找到可自动采集且口径正确的来源，加入采集配置。', '待处理', '尚无已验证的飞书可直连授权数据接口；不宣称无人值守覆盖。', 1),
(12, 'D3', '数据源待接通：公司公告及财报', '数据源', '跟踪', '找到可自动采集且口径正确的来源，加入采集配置。', '待处理', '尚未部署云端公告增量、PDF解析与内容哈希去重；不宣称每日自动研究已完成。', 1),
(45, 'Q10', '2014—2015 年营业成本缺失（毛利率从 2016 年起）', '数据源', '历史财务、驾驶舱历史图', '取得 2014—2015 年年报利润表营业成本后补齐。', '处理中', '2026-10-22：岗底斯知识库补齐 2016—2022 年营业成本与 2014—2022 年归母净资产（2018 年营业成本为评级报告毛利率推算）；Wind 积分不足，岗底斯结构化接口只覆盖近三年。', 1);
INSERT INTO vi_change_log_base (id, change_date, title, target, old_value, new_value, reason, basis, verification, company_id) VALUES
(1, '2026-09-19', '建立 V2 研究与估值链', '工作台结构与估值链', '10张原表+旧估值看板', '增加V2研究、证据、映射、输入、公式、决策、监控与质量层', '用户要求可复用价值投资数据库；保留旧模型对照，分离事实判断与现金口径', '本地快照20260919T153616；原表未覆盖', '78项工程检查通过；财务证据仍待核验', 1),
(2, '2026-09-20', '隔离水文负流量观察', 'V2_11市场观察及三峡历史看板', '三条负流量观察混入有效看板', '原记录保留；质量有效=0，图表排除；备用采集拒收负数及非有限值', '入库流量出现-14200、-10000、-4900；未经来源核验，不擅自变更为正数', 'Z3791116 2026-08-27/09-07；K4903912 2026-08-31；原Wind响应留存', '隔离完成；原始水文事实待核验', 1),
(3, '2026-09-20', '飞书云端自动采集上线', 'V2云端自动化、市场观察与看板', '本机Wind采集+Codex定时；电脑离线不可执行', '9条飞书原生工作流：3采集、3入库、3异常自检；18:30/18:40/19:10；本机定时暂停', '满足电脑与Codex离线仍采集的要求；保留原始响应、日期、口径与去重轨迹', 'V2_14六次真实抓取；V2_11新增3条观测；V2_15三项正常自检记录', '三来源工程链路通过；三峡/向家坝入库流量与公告PDF仍待接通；正式模型假设未改', 1),
(4, '2026-09-25', '表内联动改造', '年度假设、情景控制、估值链、市场观察与质量检查', '年度共同参数逐年重复、情景股本和估值年份重复、跟踪任务最新观察为固定文字', '基准输入加单年覆盖；无风险利率1.69%与风险溢价3.5%在表内相加并按0.1个百分点取整为5.2%；公式贯通财务引擎、估值与敏感性；市场观察回查原始采集并汇总到跟踪任务；现金桥接状态实时计算；历史折旧与财务费用缺项保留空白；质量检查及驾驶舱图实时勾稽', '减少重复录入并保留原始输入、证据与估值结果之间的可追溯关系', '2026-09-25线上快照与逐行数值对账；V2_04来源证据连接LEGACY-FORECAST', '三情景、30财务行、25敏感性、5沙盘改造前后数值一致；17条云端观察均匹配原始采集；历史完整5年合计未变、缺项7年由误示0改为空白；现金口径及旧利率来源仍待核验', 1),
(5, '2026-10-21', '飞书目录精简', '工作台目录、表名、默认视图、使用指南、驾驶舱文字', '根目录26张表平铺（V1十张与V2混放）；表名V2_00—V2_15编号与目录顺序不一致；默认视图显示全部字段（财务引擎44列）；使用指南12条；工作流名带V2前缀', '驾驶舱＋使用指南＋5个文件夹（1研究/2估值/3跟踪/4后台/5归档）；表名按阅读顺序编号1.1—4.2；每表默认“日常”视图只留关键列，另设“全部字段”视图；使用指南合并为9条并新增表格地图；工作流按①采集②入库③自检命名；Wind停更图表标注；V1十张表、旧估值看板和两份旧文档移入归档', '让人按“研究→估值→跟踪”的顺序理解框架；不改任何字段、公式、记录数值和工作流逻辑', '改前本地备份：表结构、全部记录、视图字段、看板配置、工作流定义；本地audit.py与monitor.py改为按表ID访问', 'audit.py 83项通过0失败；三情景条件DDM 14.24/26.19/36.65元与改前一致；工作流与看板引用随表ID自动更名', 1),
(6, '2026-10-21', '从飞书迁移到本机 NocoBase', '全部表、公式、页面、工作流', '飞书多维表格（26 张表、169 个公式、9 条云端工作流）', 'NocoBase＋PostgreSQL：公式改写为 SQL 视图，页面与工作流重建', '用户决定脱离飞书', '逐格对比 8399 个单元格，0 处差异', '迁移当时的全部输入与计算结果与飞书一致', 1),
(7, '2026-10-21', '补齐历史年度与季度数据', '归档·年度数据、归档·季度跟踪', '2014—2022 发电量/电价/营收/折旧/财务费用/CFO/资本开支多为空；带息负债仅 2023/2024；投资收益仅 2024/2025；季度跟踪止于 2026H1', '空缺项按 Wind 补齐（旧值不改）；季度跟踪新增 2025Q3、2025Q4、2026Q1、2026Q3', '用户要求尽可能补齐数据', 'WIND-FIN-2014-2025；WIND-GEN-S0069453；ANN-GEN-2025Q3/2025FY/2026Q1/2026Q3', '数据库取数，口径差异见证据“口径与局限”；发电量公告已读原文', 1),
(8, '2026-10-21', '填入现金桥接建议值', '2.2 年度假设 2026—2035 现金桥接 9 项', '9 项全空；FCFE、现金支持分红、现金支持DDM 不输出', '按 CASHBRIDGE-PROPOSAL-20261021 填入建议值；条件DDM 不受影响', '用户要求尽可能补齐数据；以 2023—2025 合并报表实际值为锚', 'GTS-FS-2023-2025；CASHBRIDGE-PROPOSAL-20261021', '建议值待核验：维持/扩张资本拆分、扩张节奏、净借款为判断；需用户确认后才可视为正式假设', 1),
(9, '2026-10-21', '重构为通用价值投资框架', '数据结构、估值公式、页面', '飞书迁移结构：V1/V2 两套模型并存；证据账本含 JSON；综合负担率；利息手填；年份与情景名写死在公式里', '通用框架 vi_：公司/论点/来源/事实/判断/历史财务/定期经营/指标/观察/模型/情景/逐年假设/试验/跟踪/问题/日志；税与少数股东拆分；利息由债务滚动计算；价值滚动到估值日；论点证伪自动检查；自动检查 12 项；采集配置化', '用户要求数据人能读懂，并可复用到其他公司', 'framework/ 与 companies/600900_长江电力/', '见回归核对：条件 DDM 与重构前一致（差异来自税/少数股东拆分与债务成本取整，见 README）', 1),
(10, '2026-10-21', '新增资产侧滚动与财务模型可视化页', '估值模型（期初资产负债 4 项）、资产与资本报表、财务模型页面', '只有带息负债滚动，没有资产负债；利润计算只能在“预测计算”宽表里看', '经营性长期资产、长期股权投资、带息负债、归母与少数股东权益逐年滚动，平衡项＝其他净资产；ROE、带息负债率、利息保障倍数、带息负债÷EBITDA；“财务模型”页用瀑布图逐步展示营收→利润→股息→现金', '用户要求看清从营收到利润怎么算，资产另算', '2025 年末合并资产负债表（岗底斯）', '其他净资产逐年变化＝FCFE−股息＋少数股东留存＋少数股东折旧−其他现金调整＋营运资本增加，十年逐年一致', 1),
(11, '2026-10-22', '验证采集工作流并新增“立即采集”按钮', '工作流 ①②③（新版本）与 ④、采集运行表、原始采集记录、驾驶舱', '三条定时工作流从未实际运行；抓取失败与解析失败混在“校验失败”里；没有手动触发入口', '①②③ 实测可运行；入库/自检逻辑移入 SQL 函数 vi_ingest()/vi_selfcheck()；原始记录增加抓取结果，新增“抓取失败”状态；新增采集运行表与工作流 ④（按钮新增一行即触发，采集→入库→自检一次跑完）', '用户要求验证自动采集并加一个“按一下就跑一次”的按钮', '工作流执行记录；原始采集记录 105—113', '①②③ 各手动执行一次均正常结束；④ 经 API 与浏览器按钮触发，约 3 秒完成，三个数据源 HTTP 200', 1),
(20, '2026-10-22', '框架升级：按公司分列菜单，新增毛利率等历史指标', '页面菜单、历史财务、论点自动检查、驾驶舱', '所有公司的记录混在同一组页面里；驾驶舱只展示勾选“默认展示”的公司；历史财务没有毛利率、ROE 等', '顶层菜单按公司分列（长江电力、太阳纸业、框架与后台），页面只显示本公司记录，每家公司有自己的驾驶舱和财务模型；历史财务新增营业成本、归母净资产，自动计算毛利率、ROE、经营现金流÷归母净利润、资本开支÷经营现金流、净负债、净负债÷EBITDA，并可用于论点自动检查', '加入第二家公司（太阳纸业）时用户要求两个项目分列、不要混在一起', 'framework/build_pages.py、build_overview.py、spec.py', '长江电力估值结果不变（基准 27.28 元）；2023—2025 年营业成本、归母净资产来自岗底斯，2014—2022 年待补', 1);
