INSERT INTO vi_judgment_base (company_id, code, title, status, parameter, affected_years, fact_layer, judgment, transmission, change_threshold, no_change_condition, counter_evidence) VALUES
((SELECT id FROM vi_company_base WHERE code = '600900.SH'), 'J-COST', '付现成本', '研究规则', '逐年假设·付现成本', '2026—2035，全部情景（悲观情景再 ×1.05）', '2025 年倒算约 201 亿元（营收 862.4 − 折旧 195.3 − 财务费用 93.7 − 利润总额 417.4 ＋ 其他净贡献约 45）；2024 年成本费用中折旧约 38.6%、财务费用约 22.1%、规费约 7.2%、其他约 32%，大部分是刚性成本。', '付现成本 2026 年 203 亿元，此后每年约增 2 亿元（约 1%）：运行材料、薪酬、库区维护基金随通胀小幅上升；规费随电量和收入变化，但金额小，不单独建模。', '付现成本每多 10%（约 20 亿元/年），基准隐含回报约 −18bp。', '年报倒算的付现成本偏离假设 5% 以上；抽蓄、扩机投产带来新增运维成本。', '单年修理费、一次性费用波动。', '抽蓄投产后运维成本可能跳升；秘鲁路德斯公司的配售电成本口径不同，会混进合并报表。'),
((SELECT id FROM vi_company_base WHERE code = '600900.SH'), 'J-PAYOUT', '派息率', '研究规则', '逐年假设·派息率', '2026—2035，全部情景', '2026—2030 年每年现金分红不低于归母净利润的 70%，已写入公司章程；2021—2025 年实际派息率 70.6%、94.3%、73.7%、71.0%、70.9%。', '派息率 72%：承诺下限 70%，加上近三年实际略高于下限的习惯。枯水年公司会提高派息率保住每股股息（2022 年 94.3%），但不当作常态。2031 年以后没有承诺，沿用 72%。', '股息＝归母净利润 × 派息率；派息率降到 70%，基准隐含回报约 −11bp。', '公司修改或不再续签分红承诺；连续两年实际派息率低于 71% 或高于 75%。', '单年为保每股股息而提高派息率。', '大额资本开支（抽蓄、扩机、雅鲁藏布江等）或负债率上升时，派息可能停在 70% 下限；2031 年以后没有承诺。');
INSERT INTO vi_source_base (company_id, title, source_type, publisher, publish_date, reliability, verify_status, retrieved_on, summary, limitations) VALUES
((SELECT id FROM vi_company_base WHERE code = '600900.SH'), '卖方与行业研究：长江电力定价机制、消纳区域、折旧到期、扩机、抽蓄与来水（首创、开源、华泰、国信、广发、长江、南京证券等，2025-05—2026-10）', '数据库取数', '岗底斯（卖方研报、点评与电话会纪要）', NULL, '三级·第三方数据', '待核验', '2026-10-23', '经岗底斯知识库检索：六站电价定价方式与消纳区域、三峡机组折旧到期表、扩机增容约 437.5 万千瓦、抽蓄储备、投资收益平滑、六库联调增发电量、2026 年三季度来水测算、雅鲁藏布江下游水电工程、卖方估值与评级。', '转述口径，关键数字以公司公告与年报核对；卖方观点整体偏多头。'),
((SELECT id FROM vi_company_base WHERE code = '600900.SH'), '《长江电力 2025 年价值手册》（产业公众号转引）', '官方网站', '长江电力（产业公众号转引）', '2026-02-25', '三级·第三方数据', '待核验', '2026-10-23', '成本费用结构（折旧、财务费用、规费、其他）、2024 年路德斯营收与净利润。见产业公众号《长江电力“逆向”下行，是布局机遇，还是价值陷阱？》。', '二手转引，原文个别算式有误（如分电站发电量加总），只取比例类数据。'),
((SELECT id FROM vi_company_base WHERE code = '600900.SH'), '同业 2025 年年报利润表与同业对比（华能水电、国投电力、桂冠电力、川投能源、南网储能）', '数据库取数', '岗底斯（同业年报利润表、同业对比）', '2026-04-30', '三级·第三方数据', '待核验', '2026-10-23', '五家同业 2025 年营业收入、营业成本、归母净利、投资净收益；岗底斯同业对比里的 ROE、装机、利用小时与抽蓄规模。', '利润表科目来自年报；ROE、装机、利用小时来自岗底斯整理，未逐项与原文核对。'),
((SELECT id FROM vi_company_base WHERE code = '600900.SH'), '广东、江苏、浙江 2026 年度电力交易结果（电力交易中心，卖方转引）', '数据库取数', '广东、江苏、浙江电力交易中心（开源、广发转引）', '2026-01-04', '三级·第三方数据', '待核验', '2026-10-23', '2026 年年度长协交易均价及同比、较燃煤基准价的浮动。', '年度长协只代表市场化电量里的一部分，不等于公司结算电价。'),
((SELECT id FROM vi_company_base WHERE code = '600900.SH'), '研究推导：商业模式、产业链与五力、竞争对手、竞争壁垒、论点与辩论、适配度（2026-10-23）', '研究推导', '本研究', '2026-10-23', '研究推导', '待核验', '2026-10-23', '商业模式画布 9 项、产业链 10 个环节、对照公司 7 家、候选壁垒 8 项（含伪壁垒 3 项）、论点 6 条（全部做过正反辩论）、适配度 29/40 的推导过程。岗底斯观点 PK 未调用（此前三次超时），辩论按正反证据组织，裁决是判断。', '判断，不是事实。');
INSERT INTO vi_fact_base (company_id, title, category, statement, period, as_of, verify_status, source_id, notes) VALUES
((SELECT id FROM vi_company_base WHERE code = '600900.SH'), '2025 年主营构成：境内水电 756.6 亿元（毛利率 65.8%），其他 103.2 亿元（毛利率 31.5%）', '经营', '2025 年年报主营构成：境内水电行业收入 756.62 亿元（+1.59%）、营业成本 258.82 亿元、毛利率 65.79%；其他行业（主要是秘鲁路德斯公司配售电，及国内配售电、新能源）收入 103.23 亿元、毛利率 31.54%；其他业务 2.57 亿元。路德斯公司 2025 年利润总额 2.98 亿美元，较收购初期增长 42.91%；2024 年路德斯营收 89.5 亿元、净利润 13.8 亿元（价值手册）。', '2025', '2025-12-31', '已核验', (SELECT id FROM vi_source_base WHERE company_id = (SELECT id FROM vi_company_base WHERE code = '600900.SH') AND title = '长江电力 2025 年年度报告' LIMIT 1), '2024 年路德斯营收与净利润来自《2025 年价值手册》（产业公众号转引），待核验。'),
((SELECT id FROM vi_company_base WHERE code = '600900.SH'), '成本结构（2024 年）：折旧约 38.6%、财务费用约 22.1%、规费约 7.2%、其他约 32%', '财务', '2024 年成本费用中，大坝与机组折旧约 38.6%、财务费用约 22.1%（带息负债约 2,970 亿元）、资源税与城建税等规费约 7.2%（随发电量和收入变化）、运行材料、职工薪酬、库区维护基金等其他成本约 32%（大部分刚性）。约八成成本不随收入变化，经营杠杆高：2024 年营收 +8%、扣非归母 +18%；2022 年营收 −6%、扣非归母 −11%。', '2024', '2024-12-31', '待核验', (SELECT id FROM vi_source_base WHERE company_id = (SELECT id FROM vi_company_base WHERE code = '600900.SH') AND title = '《长江电力 2025 年价值手册》（产业公众号转引）' LIMIT 1), NULL),
((SELECT id FROM vi_company_base WHERE code = '600900.SH'), '所得税：母公司 25%、川云 15%、云川减半期 7.5%，乌东德、白鹤滩将退出减半期', '财务', '2025 年年报：本公司及所属子公司 25%；三峡金沙江川云水电（溪洛渡、向家坝）按西部大开发 15%（执行至 2030 年）；三峡金沙江云川水电（乌东德、白鹤滩）属公共基础设施项目“三免三减半”，叠加西部大开发，报告期减半按 7.5%；秘鲁公司 29.5%。卖方测算乌东德 2026 年、白鹤滩 2027 年退出“三免三减半”，此后按 15%；外资研报指出 2025 年与 2026 年一季度有效税率已上升。', '2025', '2025-12-31', '待核验', (SELECT id FROM vi_source_base WHERE company_id = (SELECT id FROM vi_company_base WHERE code = '600900.SH') AND title = '长江电力 2025 年年度报告' LIMIT 1), '税率来自年报；退出减半期的年份来自卖方测算（2026-06），待以公司公告核实。'),
((SELECT id FROM vi_company_base WHERE code = '600900.SH'), '三峡机组折旧到期：右岸 15—26 号 2025—2026 年，地下 27—32 号 2029—2030 年', '财务', '三峡电站 32 台 70 万千瓦机组：左岸 1—14 号 2003—2005 年投产、2021—2023 年折旧到期；右岸 15—26 号 2007—2008 年投产、2025—2026 年到期；地下 27—32 号 2011—2012 年投产、2029—2030 年到期（按 18 年机器设备折旧年限推算）。卖方纪要：2026—2031 年三峡机组每年仍有约 15 亿元以上的折旧额度到期，之后溪洛渡、向家坝机组接续到期；2025 年机组折旧减少约 3.09 亿元。', '2026—2031', '2026-07-26', '待核验', (SELECT id FROM vi_source_base WHERE company_id = (SELECT id FROM vi_company_base WHERE code = '600900.SH') AND title = '卖方与行业研究：长江电力定价机制、消纳区域、折旧到期、扩机、抽蓄与来水（首创、开源、华泰、国信、广发、长江、南京证券等，2025-05—2026-10）' LIMIT 1), NULL),
((SELECT id FROM vi_company_base WHERE code = '600900.SH'), '六库联调：2025 年节水增发电量 140.1 亿千瓦时，水能利用提高率 4.68%', '经营', '六座梯级水库由公司统一优化调度（跨长江干流 1,800 多公里、落差 900 多米、110 台机组），2025 年节水增发电量 140.1 亿千瓦时，水能利用提高率 4.68%。乌东德、白鹤滩投运后，发电量的年际波动较“十二五”时期明显降低。', '2025', '2025-12-31', '待核验', (SELECT id FROM vi_source_base WHERE company_id = (SELECT id FROM vi_company_base WHERE code = '600900.SH') AND title = '卖方与行业研究：长江电力定价机制、消纳区域、折旧到期、扩机、抽蓄与来水（首创、开源、华泰、国信、广发、长江、南京证券等，2025-05—2026-10）' LIMIT 1), '增发电量来自岗底斯同业对比引公司披露，待与年报原文核对。'),
((SELECT id FROM vi_company_base WHERE code = '600900.SH'), '扩机增容空间约 437.5 万千瓦（葛洲坝、向家坝、溪洛渡）', '资本开支', '葛洲坝扩机增容约 127.5 万千瓦（扩机 80 万千瓦，容量调整 47.5 万千瓦已于 2022 年底完成）；向家坝 184 万千瓦（扩机 144、容量调整 40）；溪洛渡容量调整 126 万千瓦。向家坝、葛洲坝扩机已纳入长江流域水电高质量发展实施方案（2025 年上半年）。扩机只需新增水轮机与发电机，不用重建大坝、厂房与线路，边际成本低。', '2026', '2026-07-07', '待核验', (SELECT id FROM vi_source_base WHERE company_id = (SELECT id FROM vi_company_base WHERE code = '600900.SH') AND title = '卖方与行业研究：长江电力定价机制、消纳区域、折旧到期、扩机、抽蓄与来水（首创、开源、华泰、国信、广发、长江、南京证券等，2025-05—2026-10）' LIMIT 1), NULL),
((SELECT id FROM vi_company_base WHERE code = '600900.SH'), '投资收益：2025 年 49.59 亿元，2020 年以来每年约 40—55 亿元', '财务', '2025 年年报：全年实现投资收益 49.59 亿元（权益法 46.16 亿元，实际收到投资分红 26.35 亿元）。卖方纪要：2020 年以来投资收益每年约 40—55 亿元，约占利润的七分之一，枯水年份可选择性兑现以平滑利润；参股对象主要是受电区域的综合能源平台与长江上游流域的水电企业（如国投电力、川投能源）。2025 年四季度有约 10 亿元非经常性收益（南网数字上市相关）。', '2025', '2025-12-31', '待核验', (SELECT id FROM vi_source_base WHERE company_id = (SELECT id FROM vi_company_base WHERE code = '600900.SH') AND title = '长江电力 2025 年年度报告' LIMIT 1), '49.59、46.16、26.35 来自年报与历史财务；区间、参股对象与非经常性收益来自卖方纪要。'),
((SELECT id FROM vi_company_base WHERE code = '600900.SH'), '受电省份 2026 年年度交易均价：广东 0.372、江苏 0.344、浙江 0.345 元/千瓦时', '政策', '2026 年年度长协：广东 372.14、江苏 344.19、浙江 344.85 元/兆瓦时，同比 −19.72、−68.26、−67.54 元/兆瓦时，较燃煤基准价下浮 17.8%、12.0%、17.0%。华泰（2026-08）：公司涉及外送电量市场化的云川、川云公司 2026 年上半年平均电价同比基本平稳。', '2026', '2026-01-04', '待核验', (SELECT id FROM vi_source_base WHERE company_id = (SELECT id FROM vi_company_base WHERE code = '600900.SH') AND title = '广东、江苏、浙江 2026 年度电力交易结果（电力交易中心，卖方转引）' LIMIT 1), '数值为江苏年度均价。'),
((SELECT id FROM vi_company_base WHERE code = '600900.SH'), '同业 2025 年毛利率：华能水电 57.0%、桂冠 54.0%、南网储能 50.8%、国投电力 41.1%，长江电力 61.7%', '经营', '2025 年年报利润表：华能水电营收 265.95 亿元、营业成本 114.41 亿元（毛利率 57.0%）、归母 85.04 亿元；桂冠电力营收 103.93 亿元（毛利率 54.0%）、归母 32.80 亿元（+43.6%）；国投电力营收 530.14 亿元（毛利率 41.1%，含火电）、归母 73.93 亿元；川投能源营收 16.68 亿元、投资净收益 48.70 亿元、归母 47.54 亿元；南网储能营收 73.77 亿元（毛利率 50.8%）、归母 16.89 亿元。ROE（岗底斯）：长江电力约 15.6%、桂冠 15.8%、川投 10.6%、华能水电 10.4%、国投电力 10.2%、南网储能 7.5%。华能水电水电装机 2811.58 万千瓦；桂冠电力 847.3 万千瓦；雅砻江水电 2025 年利用小时 4,539；南网储能抽蓄在运 1268 万千瓦、在建 1200 万千瓦。', '2025', '2025-12-31', '待核验', (SELECT id FROM vi_source_base WHERE company_id = (SELECT id FROM vi_company_base WHERE code = '600900.SH') AND title = '同业 2025 年年报利润表与同业对比（华能水电、国投电力、桂冠电力、川投能源、南网储能）' LIMIT 1), '数值为长江电力 2025 年毛利率（历史财务）。'),
((SELECT id FROM vi_company_base WHERE code = '600900.SH'), '雅鲁藏布江下游水电工程开工：6000 万千瓦以上、年发电约 3000 亿千瓦时、投资约 1.2 万亿元', '其他', '2025 年 7 月 19 日开工并组建中国雅江集团：5 座梯级电站、截弯取直隧洞引水，装机 6000 万千瓦以上、年发电约 3,000 亿千瓦时（约等于长江电力全部发电量），总投资约 1.2 万亿元（单位造价约 2 万元/千瓦，三峡约 0.93 万元/千瓦），电力以外送消纳为主。', '规划', '2025-07-19', '待核验', (SELECT id FROM vi_source_base WHERE company_id = (SELECT id FROM vi_company_base WHERE code = '600900.SH') AND title = '卖方与行业研究：长江电力定价机制、消纳区域、折旧到期、扩机、抽蓄与来水（首创、开源、华泰、国信、广发、长江、南京证券等，2025-05—2026-10）' LIMIT 1), '新华社报道，华泰、申万转引。'),
((SELECT id FROM vi_company_base WHERE code = '600900.SH'), '2022 年枯水：四站发电量 −10.9%、归母净利 −18.9%，派息率提高到 94.3%', '经营', '2022 年三峡、葛洲坝、溪洛渡、向家坝四站发电 1855.81 亿千瓦时（2021 年 2083.22，−10.9%），归母净利 213.09 亿元（2021 年 262.73，−18.9%）；派息率提高到 94.3%，保持了每股股息。', '2022', '2022-12-31', '已核验', (SELECT id FROM vi_source_base WHERE company_id = (SELECT id FROM vi_company_base WHERE code = '600900.SH') AND title = 'Wind：长江电力 2014—2025 年财务数据' LIMIT 1), '“2021 年已动用投资收益平滑业绩、2022 年平滑储备不足”的解释来自卖方纪要。'),
((SELECT id FROM vi_company_base WHERE code = '600900.SH'), '估值：2026 年 PE 约 18—19 倍、股息率约 3.6%—3.7%；近十年 PE 区间 14—29 倍', '估值方法', '卖方 2026 年 4—8 月：2026 年 PE 约 18—19 倍、股息率约 3.6%—3.7%（华泰预计 2026 年股息率 3.71%）。产业公众号（2026-02）引 Wind：PE 18.9 倍，近十年区间 14—29 倍；股价从 2025 年 7 月 29.5 元跌到约 26 元，同期跑输大盘约 30 个百分点。', '2026', '2026-08-30', '待核验', (SELECT id FROM vi_source_base WHERE company_id = (SELECT id FROM vi_company_base WHERE code = '600900.SH') AND title = '卖方与行业研究：长江电力定价机制、消纳区域、折旧到期、扩机、抽蓄与来水（首创、开源、华泰、国信、广发、长江、南京证券等，2025-05—2026-10）' LIMIT 1), NULL);
INSERT INTO vi_lnk_judgment_facts (judgment_id, fact_id, "createdAt", "updatedAt")
INSERT INTO vi_thesis_base (company_id, code, title, category, status, confidence, bull_case, bear_case, bull_rebuttal, bear_rebuttal, verdict, decisive_evidence, mind_changer, model_impact, external_view, check_metric, check_op, check_threshold, check_years, debated_on) VALUES
((SELECT id FROM vi_company_base WHERE code = '600900.SH'), 'T1', '长江干流水能资源独占且不可复制，能持续带来高于同业的稳定回报', '经营', '成立', '高', '1）资源独占（M1）：长江干流六座梯级电站装机 7169.5 万千瓦，坝址唯一；大坝寿命以百年计，葛洲坝首台机组 1981 年投产至今仍在运行。2）没有燃料成本、折旧到期后成本还在下降（M2）：境内水电毛利率 65.8%，ROE 长期约 15%—16%，高于并稳于同业（竞争对手）。3）新进入者无法复制：同等规模的新水电（雅下工程）造价高得多、要十年以上（V7）。', '1）稀缺资产不等于自由提价权：电价由国家核定或从受电省份落地价倒推，市场化电量已约占 40%，沿海电价下行会传导过来（T3）。2）“看天吃饭”：来水决定年度利润，2022 年枯水归母净利 −18.9%（T2）。3）大坝寿命不等于机组寿命：机组、闸门仍需更新改造，维持性资本开支每年数十亿元（J-CB2026）。4）政策与税费可以分享利润：水资源税、库区维护基金按电量计缴，所得税优惠到期后税率上升（V9）。', '提价权本来就不是这门生意的回报来源：资源与成本优势已经体现在 65.8% 的毛利率和约 16% 的 ROE 上；电价改革的方向（辅助服务、绿证）反而让水电的调节与绿色价值单独定价。', '约 16% 的 ROE 部分来自高杠杆（带息负债约 2,900 亿元）与投资收益；回报“稳”是因为监管把它限制在合理范围内，这更像一条收费公路，而不是有定价权的品牌。', '成立：资源壁垒真实且几乎不可复制，体现为最低的成本和最稳定的 ROE；但它带来的是“受监管的稳定回报”，不是提价权——回报的上限由电价机制决定，下限由来水决定。', '毛利率与 ROE 是否保持在同业之上；受电省份电价与公司综合电价的走势；维持性资本开支的实际水平。', '改判：核定电价下调或倒推机制全面改为市场化、综合电价连续两年下降超过 3%；或更新改造开支明显高于折旧到期释放的金额。自动检查：ROE 连续两年低于 12%。', NULL, '卖方普遍把长江电力当作“类债资产”：华泰（2026-08）预计 2026 年股息率约 3.7%，维持买入；国信（2026-05）考虑来水与市场化电价，小幅下调盈利预测。产业公众号（2026-02）讨论“布局机遇还是价值陷阱”，指出股价跑输大盘、PE 处于近三年低位。岗底斯观点 PK 未调用。', 'ROE', '<', 0.12, 2, '2026-10-23'),
((SELECT id FROM vi_company_base WHERE code = '600900.SH'), 'T2', '发电量长期围绕约 3,000 亿千瓦时的中枢波动，枯水年不会永久化', '经营', '成立', '中', '1）六站装机 7169.5 万千瓦、利用小时约 4,300，2023—2025 年发电量约 2,760—3,070 亿千瓦时（B5）。2）六库联调平滑来水（M3）：2025 年节水增发 140.1 亿千瓦时；2026 年上半年三峡偏丰、乌东德偏枯，合计仍 +4.81%。3）枯水是周期而非趋势：2022 年四站发电 −10.9%，2023 年起恢复；厄尔尼诺年份南方降水偏多。4）三季度三峡把部分来水转为库容，四季度枯水期释放：前三季度已完成年度计划（约 3,060 亿千瓦时）的 73.55%。', '1）2026 年三季度发电量 −14.89%（三峡单季 −29.23%），前三季度 −4.28%；卖方测算三季度溪洛渡、向家坝、三峡入库流量同比 −5.5%、−9.9%、−22.2%。2）气候变化可能让极端枯水更频繁；单站入库流量不能代表全流域，模型 2026 年 3,100 亿千瓦时的电量需要四季度复核。3）上游新建水库、生态与航运用水增加，会分走一部分来水和调度空间。', '一个季度的偏枯在 2022 年也出现过，公司当年用投资收益和提高派息率保住了每股股息；六座电站分布在金沙江、川江两段，同时长期偏枯的概率低。', '2022 年“保股息”靠的是把派息率提到 94.3%，这只能用一次；若连续两年偏枯，利润和股息都会下降。', '成立：约 3,000 亿千瓦时的中枢可信，年度波动约 ±10%；2026 年三季度的偏枯不改变中枢，但模型 2026 年 3,100 亿千瓦时可能偏高，四季度数据出来后复核（J-Q）。', '年度发电量与年度计划（2026 年约 3,060 亿千瓦时）的差距；分电站来水；三峡蓄水位。', '改判：长江上游的长期来水趋势显著下降。自动检查：年发电量连续两年低于 2,700 亿千瓦时。', NULL, '长江证券（2026-10）：下游来水明显转枯，电量承压限制业绩。广发证券（2026-10）：超强厄尔尼诺来袭，测算长江电力三季度发电量 −13.3%。中国电力报：前三季度完成年度计划 73.55%，四季度有望释放三峡蓄能。', '业务量', '<', 2700, 2, '2026-10-23'),
((SELECT id FROM vi_company_base WHERE code = '600900.SH'), 'T3', '电价长期稳定：受电省份电价下行对公司综合电价的影响有限', '经营', '成立', '中', '1）三峡（落地倒推、国务院核定）、葛洲坝（成本加成）的电价不随市场变动，占发电量三分之一以上，对整体电价形成支撑。2）2026 年江苏、浙江年度长协每度降约 7 分，但公司云川、川云的平均电价 2026 年上半年同比基本持平（华泰）：外送电在谈判中有议价力。3）2016—2025 年综合电价从 0.2375 升到约 0.28 元（含高电价电站并入），2023—2025 年 0.2827 / 0.2856 / 0.2807 元。4）水电的调节与绿色价值有望单独定价（辅助服务市场、绿证）。', '1）市场化电量已约占 40%，乌东德、白鹤滩全部参与市场化交易；受电省份 2026 年年度交易均价：广东 0.372（−0.020）、江苏 0.344（−0.068）、浙江 0.345（−0.068）元/千瓦时（V5）。2）新能源装机快速增长，压低午间与现货电价，市场化电价的下行可能持续多年（V6）。3）综合电价混合了其他业务与分电站结构，“综合电价稳定”可能掩盖市场化部分的下降（问题 Q02）。', '倒推电价按年度协议调整，有滞后与谈判空间；公司的落地价本来就低于受电省份的平均电价，下降空间有限。', '滞后不等于不传导：2026 年年度长协的下降会在之后的谈判里体现；“低于平均电价”恰好说明它是价格接受者。', '成立（目前）：三峡、葛洲坝的稳定电价和外送议价力抵消了大部分沿海电价下行，2026 年上半年市场化电站电价基本持平。但市场化部分已占约四成，沿海电价若继续下行，2027 年起综合电价可能有 1%—3% 的下行压力（估算：市场化占比约 40%×沿海降幅约 10%—15%×传导约一半）。', '2026 年全年综合电价；乌东德、白鹤滩的结算电价；2027 年受电省份年度交易结果。', '改判为存疑：三峡核定电价下调。自动检查：综合电价同比下降超过 3%。', NULL, '华泰（2026-08）：涉及外送电量市场化的云川、川云公司上半年平均电价同比较为平稳，展现强议价能力。国信（2026-05）：部分电量参与市场化交易可能压制综合电价。首创（2026-04）：2025—2026 年电价或有所下降，但葛洲坝、三峡电价稳定形成支撑。', '单价同比', '<', -0.03, 1, '2026-10-23'),
((SELECT id FROM vi_company_base WHERE code = '600900.SH'), 'T4', '成本退坡（折旧到期＋利息下降）推动利润中枢上移', '财务', '成立', '高', '1）三峡机组折旧陆续到期（M2）：右岸 15—26 号 2025—2026 年、地下 27—32 号 2029—2030 年到期，2026—2031 年每年仍有约 15 亿元以上的折旧到期，之后溪洛渡、向家坝接续。2）财务费用 2023—2025 年 125.56 → 111.31 → 93.71 亿元，还本叠加低息置换（新发中票 2.05%、超短融 1.32%，M4）；2026 年上半年再降 13.61%。3）卖方测算：折旧到期、利息下降、投资收益增长合计，未来五到十年 EPS 年化约 4%。', '1）折旧下降提升利润，但不等额增加现金：机组到期后仍要更新改造，维持性资本开支会上升（J-DA、J-CB2026）。2）抽水蓄能、葛洲坝航运扩能（约 266 亿元）、新能源等新项目会重新增加折旧与利息。3）利率上行时低息置换的空间消失；乌东德、白鹤滩所得税减半期结束，会抵消一部分成本下降。', '新项目的折旧与利息由它们自己的收入覆盖；存量电站的成本退坡是确定的，不依赖任何假设。', '抽蓄的资本金回报约 6.5%，新项目的利润率远低于存量电站，会摊薄整体利润率的上升。', '成立：未来五年利润中枢上移的确定性高（每年约 15 亿元折旧到期、十多亿元利息下降），但对现金的贡献小于对利润的贡献；所得税率上升会抵消一部分。', '年度折旧与财务费用；维持性资本开支；新项目的投资进度。', '改判：财务费用止降回升且折旧不再下降。自动检查：财务费用同比上升。', '所得税率不在假设依据里，见待办清单 Q11', '开源（2025-05）、国盛（2025-08）：三峡机组折旧到期与财务费用下降是利润增长的主要来源。长江证券纪要（2026-07）：2026—2031 年三峡每年 15 亿元以上折旧到期，利息每年下降十多亿元。', '财务费用同比', '>', 0, 1, '2026-10-23'),
((SELECT id FROM vi_company_base WHERE code = '600900.SH'), 'T5', '分红承诺（不低于归母净利 70%）可信且可持续', '治理', '成立', '中', '1）2026—2030 年现金分红不低于当年归母净利 70%，已写入公司章程；2021—2025 年实际派息率 70.6%—94.3%。2）2022 年枯水年把派息率提到 94.3%，保住了每股股息。3）经营现金流是归母净利的 1.76 倍（B9），控股股东三峡集团 2026 年增持 44.99 亿元，与少数股东利益一致。', '1）现金桥接显示 2026—2029 年 FCFE 低于计划股息：扩张资本（抽蓄、葛洲坝航运扩能）和每年约 100—120 亿元的还债要和分红共用同一笔现金（J-CB2026）。2）不能同时承诺高分红、快速去杠杆和大规模扩张：扩张加速时，要么放慢还债，要么借钱分红。3）70% 是下限，不是增长：每股股息的增长只能来自利润增长（约 3%—4%/年）。', '还债速度可以调：2024—2025 年年均净还债约 124 亿元，放慢一点就能覆盖股息缺口，带息负债率仍在下降。', '放慢还债意味着利息下降变慢，T4 的利润增长会打折扣；利率上行时“借钱分红”会侵蚀价值。', '成立：70% 的下限可信（章程约束、现金流充沛、历史兑现）；但扩张期的股息靠“还债速度”调节，现金支持价值偏紧，不宜预期派息率明显高于 72%。', '年度派息率与每股股息；年度资本开支与净还债；母公司可分配利润与现金。', '改判：以股票股利替代现金分红。自动检查：派息率低于 70%。', '派息率直接写在逐年假设里', '国泰海通（2026-01）：明确 2026—2030 年归母净利 70% 现金分红比例，高股息、稳现金流资产稀缺性凸显。长江证券纪要（2026-07）：2016 年的长期分红承诺是估值的分水岭。', '派息率', '<', 0.7, 1, '2026-10-23'),
((SELECT id FROM vi_company_base WHERE code = '600900.SH'), 'T6', '新增投资（抽水蓄能、扩机、航运扩能、对外投资）的回报高于资本成本，不摊薄每股价值', '治理', '观察', '低', '1）扩机增容约 437.5 万千瓦几乎不用新建大坝和厂房，边际成本极低（铭牌变更几乎零成本）。2）抽水蓄能实行两部制电价，容量电价按经营期定价法核定（资本金内部收益率约 6.5%），收益有保障且高于 6% 的门槛。3）对外投资（受电区域能源平台与上游水电）每年贡献约 40—55 亿元投资收益，在枯水年平滑利润。', '1）抽蓄是“受管制的合理回报”：资本金回报 6.5% 只略高于股权成本，已在运的南网储能 ROE 只有 7.5%（竞争对手），规模越大、整体 ROE 越被摊薄（M8）。2）葛洲坝航运扩能约 266 亿元主要服务航运，回报要靠后续扩机电量覆盖新增折旧（约 6 亿元/年），不确定。3）历史增长主要靠控股股东资产注入（伪壁垒 M7），注入价格决定回报；长江干流已没有大型待注入电站。4）投资收益里只有约一半以现金分回（B9）。', '6.5% 的资本金回报在约 2% 的借款成本下仍有正利差；电力市场化后，抽蓄的调节价值可能高于核定水平。', '正利差来自杠杆，不是生意本身；按“每股长期现金回报”衡量，新投资目前看不到超过存量水电的回报。', '观察：扩机增容回报很高，抽蓄与航运扩能只能算“合理回报”，对外投资回报尚可但现金回收约一半。总体不会明显摊薄每股价值，但也很难让 ROE 超过 16%；关键看投资节奏与关联交易定价。', '抽蓄项目的实际造价与投产时间（甘肃张掖、湖南攸县进度靠前）；扩机项目的核准与投产；对外投资的现金分红率；关联交易定价。', '改判为存疑：出现大额低回报并购或增持（投入资本回报低于 6% 门槛），或抽蓄造价明显超支。改判为成立：扩机投产、抽蓄实际回报高于核定水平。', NULL, '长江证券纪要（2026-07）：抽水蓄能当前盈利水平不及常规水电，但调节性资源稀缺，中长期收益率有提升潜力。国盛（2025-08）：葛洲坝航运扩能年均约 35 亿元支出，对分红影响有限，扩机 80 万千瓦可对冲新增折旧。', NULL, NULL, NULL, NULL, '2026-10-23');
INSERT INTO vi_lnk_thesis_facts (thesis_id, fact_id, "createdAt", "updatedAt")
INSERT INTO vi_lnk_judgment_theses (judgment_id, thesis_id, "createdAt", "updatedAt")
INSERT INTO vi_biz_model_base (company_id, code, element, title, content, metric, trend) VALUES
((SELECT id FROM vi_company_base WHERE code = '600900.SH'), 'B1', '客户细分', '两大电网公司，电量最终送往长三角、珠三角和华中', '电卖给国家电网、南方电网，终端在受电省份：三峡丰水期送广东、华东各半，枯水期广东 16%、华东 32%、华中 52%；溪洛渡送浙江、广东，向家坝送上海，乌东德送广东、广西并留存云南，白鹤滩送江苏、浙江并留存四川、云南。', '受电区域是全国电价最高的长三角、珠三角', '外送电与受电省份的本地电源（煤电、核电、新能源）在价格上可比，受电省份电价下行会传导到倒推电价和市场化电价（T3）。'),
((SELECT id FROM vi_company_base WHERE code = '600900.SH'), 'B2', '价值主张', '清洁、可调节的大规模电力', '年发电约 3,000 亿千瓦时，可满足 3 亿多人一年的用电。水电没有燃料成本、出力可快速调节，在新能源占比上升的电力系统里兼有电量、调峰与绿色价值；常规水电已纳入绿证核发。', '年发电约 3,000 亿千瓦时', '电力市场化后，调节价值（辅助服务、调峰）有望单独定价；电量价值则随受电省份电价走（V5、T3）。'),
((SELECT id FROM vi_company_base WHERE code = '600900.SH'), 'B3', '渠道通路', '特高压外送通道，不需要获客', '电量通过配套的特高压直流外送到华东、广东，属于国家“西电东送”的骨干电源，由电网保障消纳；没有营销与获客成本。', '销售费用率约 0.2%—0.3%', '外送通道容量与电网调度决定送出上限；受电省份对外来电的接纳与价格谈判是唯一的“渠道”风险（V4、V5）。'),
((SELECT id FROM vi_company_base WHERE code = '600900.SH'), 'B4', '客户关系', '大宗中长期合同、按月结算，电价由政策机制决定', '与两大电网签大宗中长期合同、按月结算，客户只有两家，但电网保障消纳，不存在“丢客户”。电价按机制定：葛洲坝成本加成；三峡按受电省份落地电价倒推（落地价−输电价−线损）；金沙江四站为倒推电价加市场化电价，白鹤滩过渡期后全部市场化（事实摘录“电价机制”）。关系稳定来自管制，不来自公司自身（伪壁垒 M5）。', '客户 2 家（国家电网、南方电网）；按月结算', '市场化电量占比上升后，价格更多随受电省份的年度交易均价走（2026 年广东、江苏、浙江年度长协均下降，T3）。'),
((SELECT id FROM vi_company_base WHERE code = '600900.SH'), 'B5', '收入来源', '发电量×电价：境内水电约 88%，来水决定年度波动', '收入＝发电量×上网电价（发电量＝装机×利用小时）。2025 年：境内水电 756.6 亿元（毛利率 65.8%）；其他行业 103.2 亿元（毛利率 31.5%），主要是秘鲁路德斯公司（配售电）、国内配售电与新能源；投资收益 49.59 亿元不在营收里（B8）。单价与利用率：综合电价 0.2807 元/千瓦时，利用小时约 4,280（3071.94 亿千瓦时÷7169.5 万千瓦）。驱动：短期发电量随来水波动（2022 年枯水、2026 年三季度偏枯），六库联调平滑一部分（M3）；长期装机已基本到顶，新增只来自扩机增容（约 437.5 万千瓦）和抽水蓄能（2028 年起才有收入，T6）。', '2025 年：发电量 3071.94 亿千瓦时、综合电价 0.2807 元/千瓦时、营收 862.42 亿元；境内水电占营收约 88%、占毛利约 94%；2023—2025 年发电量 2762.63 / 2959.04 / 3071.94 亿千瓦时', '收入端取决于来水（T2）和电价（T3），度电收入受市场化电价压制；国际与配售电业务毛利率低，受汇率与当地监管影响；气候变化与连续枯水是主要的不确定性；资产注入式的增长已基本结束（M7）。'),
((SELECT id FROM vi_company_base WHERE code = '600900.SH'), 'B6', '核心资源', '长江干流六座梯级电站', '六座梯级电站（三峡、白鹤滩、溪洛渡、乌东德、向家坝、葛洲坝）沿长江干流 1,800 多公里排列，水位落差 900 多米，开发权与坝址不可复制（M1）。电站由三峡集团建成后注入公司（2016 年溪洛渡、向家坝，2023 年乌东德、白鹤滩）；同一条河上的六座水库可以联合调度（M3）。', '水电总装机 7179.5 万千瓦，境内六站 7169.5 万千瓦；全球前 12 大水电站占 5 座（价值手册）', '资产注入是历史上最大的增长来源，2016、2023 年两轮之后已基本完成；之后看扩机、抽蓄（M8）与参股企业的投产（T6）。'),
((SELECT id FROM vi_company_base WHERE code = '600900.SH'), 'B7', '关键业务', '梯级联合调度、电站运维，转向抽蓄与扩机建设', '电站运行与六库联合调度（多蓄水、少弃水，提高水能利用率）、大坝与机组的检修维护、库区管理；扩机增容与抽水蓄能建设；对外股权投资与国际配售电运营。', '六库联调：2025 年节水增发电量 140.1 亿千瓦时，水能利用提高率 4.68%', '运营上的提升空间有限，未来几年的重点从“运营”转向“建设”（抽蓄、葛洲坝航运扩能），资本开支上升（B9）。'),
((SELECT id FROM vi_company_base WHERE code = '600900.SH'), 'B8', '重要合作', '控股股东三峡集团、参股上下游能源企业', '控股股东三峡集团建设电站再注入公司（B6），2026 年增持 44.99 亿元。参股受电区域和长江上游的能源企业（如国投电力、川投能源），投资收益在枯水年平滑利润（事实摘录“投资收益”）。', '2025 年投资收益 49.59 亿元（权益法 46.16 亿元），2020 年以来每年约 40—55 亿元', '参股企业的投产与分红决定投资收益的增长（T6）；权益法收益只有一部分以现金分回（B9）。'),
((SELECT id FROM vi_company_base WHERE code = '600900.SH'), 'B9', '成本结构', '没有燃料，成本约八成固定；现金远多于利润', '成本约八成是固定的：2024 年成本费用中折旧约 38.6%、财务费用约 22.1%、资源税与城建税等规费约 7.2%、材料、薪酬与库区维护基金等约 32%。折旧、利息不随发电量变化，规费随收入变化，所以利润对发电量和电价高度敏感（经营杠杆高），对成本几乎不敏感。所得税：母公司 25%，川云（溪洛渡、向家坝）15%，云川（乌东德、白鹤滩）减半期 7.5%。单位利润：每度电收入约 0.28 元、归母净利约 0.112 元（345.03 亿÷3071.94 亿千瓦时），其中折旧约 0.064 元/千瓦时是非现金成本。现金：折旧不付现，2025 年经营现金流 605.63 亿元，是归母净利的 1.76 倍；资本开支 184.88 亿元（含扩张），分红约 245 亿元（派息率 70.9%），净还债约 95 亿元。权益法收益 46.16 亿元里只有 26.35 亿元以现金分红收回，所以归母利润与可分配现金之间要做桥接（J-CASH）。', '2025 年：毛利率 61.7%、归母净利 345.03 亿元、折旧 195.29 亿元、财务费用 93.71 亿元（−17.60 亿元）；度电收入 0.281 元、度电归母净利 0.112 元；经营现金流÷归母净利 1.76；资本开支÷经营现金流 0.31', '折旧到期与还债降息让成本逐年下降、度电利润上升（T4），卖方测算未来五到十年 EPS 年化约 4%；乌东德、白鹤滩将退出所得税减半期，税率会上升（待办清单 Q11）；2026—2030 年扩张资本开支（抽蓄、葛洲坝航运扩能）会抬高资本开支，现金桥接显示部分年份 FCFE 低于计划股息（J-CB2026、T5）。');
INSERT INTO vi_lnk_biz_model_facts (biz_model_id, fact_id, "createdAt", "updatedAt")
INSERT INTO vi_value_chain_base (company_id, code, position, participant, role, force, power, effect, trend, profit_share, analysis, counter) VALUES
((SELECT id FROM vi_company_base WHERE code = '600900.SH'), 'V1', '本公司环节', '长江电力：六座梯级电站的运行、联合调度与检修', '发电、梯级联合调度、电站运维', '不适用', '中', '中性', '稳定', '境内水电毛利率 65.8%（2025 年）', '公司是产业链里唯一拥有长江干流水能的一环；利润由“电价×发电量−固定成本”决定，运营上能做的是联合调度多发电、控制成本与财务费用。', '电价不由公司决定（V5、V9），超额利润主要来自资源与成本，而不是议价。'),
((SELECT id FROM vi_company_base WHERE code = '600900.SH'), 'V2', '上游供给', '长江来水与上游调度（长江委统一调度，防洪、航运、生态用水优先）', '水能', '不适用', '强', '中性', '稳定', '水是免费的；水资源税、库区维护基金按发电量计缴', '水不受公司控制：来水决定年度发电量（偏枯年份发电 −10% 以上），发电服从防洪与航运调度。这是这门生意唯一的“上游”，也是年度波动的来源。', '六库联调能把一部分来水波动熨平（M3）；上游新建水库增加了全流域的调节能力。'),
((SELECT id FROM vi_company_base WHERE code = '600900.SH'), 'V3', '上游供给', '设备与工程：东方电气、哈尔滨电气等；新电站由控股股东三峡集团建设', '水轮发电机组、更新改造与扩机；大坝与电站建成后注入', '供应商议价能力', '弱', '有利', '稳定', '维持性资本开支约 55 亿元/年（模型假设，J-CB2026）', '电站建成后，对设备商的依赖只剩更新改造与扩机，金额小、可招标；最大的“供应商”其实是控股股东——它负责建设新电站，再按评估价注入公司。', '注入的定价与时机由控股股东主导，是少数股东要看住的环节（伪壁垒 M7、T6）。'),
((SELECT id FROM vi_company_base WHERE code = '600900.SH'), 'V4', '下游客户', '国家电网、南方电网（单一买方）', '大宗中长期购电合同，按月结算', '买方议价能力', '中', '中性', '稳定', '—', '电网是唯一的买方，但不压价：电价由国家核定（三峡、葛洲坝）或从受电省份落地价倒推，电网按月结算，几乎没有坏账。', '电网的调度与外送通道安排决定能送出多少电；受电省份希望多用本地电源时，外来电的份额会被挤压。'),
((SELECT id FROM vi_company_base WHERE code = '600900.SH'), 'V5', '下游客户', '受电省份的电力市场（广东、江苏、浙江、上海、华中）', '市场化交易电量，以及倒推电价的参照', '买方议价能力', '中', '不利', '增强', '市场化电量约占 40%（年度长协价格见事实摘录）', '受电省份的电价是公司电价的“锚”：倒推电价跟着落地价走，乌东德、白鹤滩的电量全部参与市场化交易；2026 年沿海年度长协明显下降（论证见 T3）。', '2026 年上半年云川、川云平均电价同比基本持平（华泰）；三峡、葛洲坝电价不随市场变动。'),
((SELECT id FROM vi_company_base WHERE code = '600900.SH'), 'V6', '替代品', '受电省份的本地电源：煤电、核电、风电与光伏', '同一电网里竞争电量与价格', '替代品威胁', '中', '不利', '增强', '—', '新能源装机快速增长，午间电价下行、现货价格波动加大；煤价下行也降低了煤电报价。水电成本最低、可调节，在电量排序里总在前面，但价格要跟市场走。', '新能源越多，可调节电源越稀缺：水电的调峰、调频价值有望通过辅助服务市场单独定价（发改价格〔2024〕196 号）。'),
((SELECT id FROM vi_company_base WHERE code = '600900.SH'), 'V7', '潜在进入者', '新的大型水电基地：雅鲁藏布江下游（中国雅江集团），以及金沙江上游、澜沧江上游', '同样以外送为主的清洁电量', '新进入者威胁', '弱', '中性', '增强', '雅下工程的发电量约等于公司全部发电量', '长江干流的坝址已开发完，没有人能在长江上再建一座三峡；但西部新的大水电基地建成后同样外送东部，会和公司争夺受电省份“外来清洁电”的份额与输电通道（规模与造价见竞争对手：中国雅江集团）。', '新基地造价高、建设期十年以上，外送方向未定（见竞争对手）。'),
((SELECT id FROM vi_company_base WHERE code = '600900.SH'), 'V8', '同业竞争', '其他流域的大水电：华能水电（澜沧江）、雅砻江水电（国投电力、川投能源）、桂冠电力（红水河）', '各自流域独立经营', '行业内竞争', '弱', '有利', '稳定', '同业 2025 年毛利率 41%—57%；长江电力 61.7%', '水电资源按流域割据，彼此不抢客户，同业更多是“对照组”（对比见竞争对手）。外送到同一受电省份时（如雅砻江锦官电源送江苏），在市场化电量上有间接竞争。', '雅砻江水电利用小时更高（2025 年 4,539 小时），单位资产的发电效率并不输公司；华能水电还有大水电增量。'),
((SELECT id FROM vi_company_base WHERE code = '600900.SH'), 'V9', '监管', '国家发改委（电价）、国家能源局、长江委（调度）、财政与税务', '电价核定、防洪调度、水资源税与库区基金、所得税优惠', '不适用', '强', '中性', '稳定', '资源税、城建税等规费约占成本费用 7.2%（2024 年）', '电价由政府核定或按机制倒推，水资源税与库区维护基金按发电量计缴，所得税优惠按项目到期（乌东德、白鹤滩将退出减半期）：监管既保护了稳定，也封住了提价空间。', '政策方向是让水电的调节价值与绿色价值单独定价（辅助服务、绿证），对水电是增量。'),
((SELECT id FROM vi_company_base WHERE code = '600900.SH'), 'V10', '互补方', '抽水蓄能、金沙江下游水风光一体化新能源、特高压通道', '与水电互补的调节资源与外送能力', '不适用', '中', '有利', '增强', '抽蓄在建约 800—900 万千瓦；资本金内部收益率约 6.5%', '公司在金沙江下游建设水风光一体化新能源，用水电的调节能力打捆外送；抽水蓄能是新的调节资产，2028 年起陆续投产。', '新能源与抽蓄的回报率低于存量水电，规模越大，整体回报越被摊薄（T6）。');
INSERT INTO vi_lnk_value_chain_facts (value_chain_id, fact_id, "createdAt", "updatedAt")
INSERT INTO vi_competitor_base (company_id, name, ticker, relation, segment, scale_label, scale_value, scale_unit, paying_rate, price_point, gross_margin, growth, as_of, strategy, vs_us, threat, trend, source_id) VALUES
((SELECT id FROM vi_company_base WHERE code = '600900.SH'), '华能水电', '600025.SH', '同业对标', '澜沧江流域水电（送深圳、广东，留云南）', '水电装机', 2811.58, '万千瓦', NULL, '上游送深圳按落地倒推（3 年一核定）；下游送广东按年度协议；留云南参与省内市场化交易', 0.57, 0.069, '2025-12-31', '澜沧江流域独家开发，“云电外送”核心企业；上游仍有可开发的大水电，推进水风光一体化。', '强项：国内唯一还有大规模水电增量的上市公司。弱项：装机约为长江电力的 39%；留云南的电量随省内供需定价，波动更大；ROE 约 10.4%。', '低', '上升', (SELECT id FROM vi_source_base WHERE company_id = (SELECT id FROM vi_company_base WHERE code = '600900.SH') AND title = '同业 2025 年年报利润表与同业对比（华能水电、国投电力、桂冠电力、川投能源、南网储能）' LIMIT 1)),
((SELECT id FROM vi_company_base WHERE code = '600900.SH'), '国投电力（雅砻江水电）', '600886.SH', '同业对标', '雅砻江流域水电（锦官电源部分外送江苏）', '雅砻江水电利用小时', 4539, '小时', NULL, '外送江苏部分按落地倒推、与江苏电价联动；留四川执行丰枯电价', 0.411, -0.083, '2025-12-31', '以雅砻江流域水电为核心，中游卡拉、孟底沟等电站在建，两河口混蓄、道孚抽蓄同步推进。', '强项：利用小时高于长江电力（约 4,280）。弱项：单一流域集中、来水敏感（2026 年上半年水电发电量 −17.4%）；合并口径含火电，ROE 约 10.2%。外送江苏的电量与长江电力在同一市场。', '低', '稳定', (SELECT id FROM vi_source_base WHERE company_id = (SELECT id FROM vi_company_base WHERE code = '600900.SH') AND title = '同业 2025 年年报利润表与同业对比（华能水电、国投电力、桂冠电力、川投能源、南网储能）' LIMIT 1)),
((SELECT id FROM vi_company_base WHERE code = '600900.SH'), '桂冠电力', '600236.SH', '同业对标', '红水河流域水电（留广西、外送广东）', '装机', 847.3, '万千瓦', NULL, '省内标杆电价；外送部分与广东协商', 0.54, 0.083, '2025-12-31', '大唐集团红水河平台，龙滩电站调节库容大；市场化电量占比多在 20% 以下；2025 年底集团注入西藏清洁能源资产。', '强项：来水偏丰年份 ROE 约 15.8%、市场化比例低。弱项：体量约为长江电力的 12%，利润随来水大幅波动（2025 年归母 +43.6%）。', '低', '稳定', (SELECT id FROM vi_source_base WHERE company_id = (SELECT id FROM vi_company_base WHERE code = '600900.SH') AND title = '同业 2025 年年报利润表与同业对比（华能水电、国投电力、桂冠电力、川投能源、南网储能）' LIMIT 1)),
((SELECT id FROM vi_company_base WHERE code = '600900.SH'), '川投能源', '600674.SH', '同业对标', '水电投资平台（雅砻江 48%、大渡河 20%）', '雅砻江水电持股', 48, '%', NULL, NULL, 0.507, 0.036, '2025-12-31', '投资控股平台：利润主要来自参股雅砻江水电和大渡河水电的投资收益（2025 年投资净收益 48.70 亿元，营收只有 16.68 亿元）。', '和长江电力的“参股投资”部分相似，但没有自主运营的大电站；长江电力也是它的股东之一。', '低', '稳定', (SELECT id FROM vi_source_base WHERE company_id = (SELECT id FROM vi_company_base WHERE code = '600900.SH') AND title = '同业 2025 年年报利润表与同业对比（华能水电、国投电力、桂冠电力、川投能源、南网储能）' LIMIT 1)),
((SELECT id FROM vi_company_base WHERE code = '600900.SH'), '南网储能', '600995.SH', '同业对标', '抽水蓄能与新型储能（南方五省区）', '抽蓄在运装机', 1268, '万千瓦', NULL, '两部制电价（容量电价按经营期定价法核定）', 0.508, 0.195, '2025-12-31', '南方电网旗下抽蓄平台：在运 1268 万千瓦、在建 1200 万千瓦，“十五五”末目标 2100 万千瓦。', '对照意义：抽水蓄能是长江电力的新方向（在建约 800—900 万千瓦，2028 年起投产）；南网储能已在运，ROE 只有约 7.5%，说明抽蓄是“受管制的合理回报”。', '低', '上升', (SELECT id FROM vi_source_base WHERE company_id = (SELECT id FROM vi_company_base WHERE code = '600900.SH') AND title = '同业 2025 年年报利润表与同业对比（华能水电、国投电力、桂冠电力、川投能源、南网储能）' LIMIT 1)),
((SELECT id FROM vi_company_base WHERE code = '600900.SH'), '中国雅江集团（雅下水电）', NULL, '潜在进入者', '外送东部的清洁电量', '规划装机', 6000, '万千瓦', NULL, NULL, NULL, NULL, '2025-07-19', '雅鲁藏布江下游 5 座梯级电站，截弯取直、隧洞引水，总投资约 1.2 万亿元，电力以外送消纳为主。', '强项：规模约等于长江电力全部发电量，同为国家工程。弱项：单位造价约 2 万元/千瓦，是三峡的两倍多，需要更高电价；建设期长，外送方向与通道未定。', '低', '上升', (SELECT id FROM vi_source_base WHERE company_id = (SELECT id FROM vi_company_base WHERE code = '600900.SH') AND title = '卖方与行业研究：长江电力定价机制、消纳区域、折旧到期、扩机、抽蓄与来水（首创、开源、华泰、国信、广发、长江、南京证券等，2025-05—2026-10）' LIMIT 1)),
((SELECT id FROM vi_company_base WHERE code = '600900.SH'), '受电省份的煤电与新能源（以江苏、广东为例）', NULL, '替代品', '受电省份的本地电量', NULL, NULL, NULL, NULL, '2026 年年度交易均价：江苏 0.344、广东 0.372 元/千瓦时', NULL, NULL, '2026-01-04', '煤电按煤价报价；新能源装机快速增长，午间电价下行；两者共同决定受电省份的市场化电价。', '强项：本地电源、规模大，决定市场价格。弱项：煤电有燃料成本、新能源出力不稳定；水电成本最低、可调节，在电量排序里靠前。', '中', '上升', (SELECT id FROM vi_source_base WHERE company_id = (SELECT id FROM vi_company_base WHERE code = '600900.SH') AND title = '广东、江苏、浙江 2026 年度电力交易结果（电力交易中心，卖方转引）' LIMIT 1));
INSERT INTO vi_lnk_competitor_facts (competitor_id, fact_id, "createdAt", "updatedAt")
INSERT INTO vi_lnk_value_chain_competitors (value_chain_id, competitor_id, "createdAt", "updatedAt")
INSERT INTO vi_moat_base (company_id, code, title, moat_type, verdict, strength, trend, mechanism, financial_link, evidence, counter, replication, threats, check_metric, check_op, check_threshold, check_years) VALUES
((SELECT id FROM vi_company_base WHERE code = '600900.SH'), 'M1', '长江干流六座梯级电站的开发权与坝址（不可复制的水能资源）', '牌照与资源', '真实壁垒', '强', '稳定', '长江干流的坝址已全部开发，由公司（经三峡集团注入）持有，没有对手能再建一座三峡；大坝按 40—60 年折旧，实际寿命以百年计。', '境内水电毛利率 65.8%（2025 年）；ROE 长期约 15%—16%，高于其他水电（约 10%—16%）且更稳定（对比见竞争对手）。', '境内装机 7169.5 万千瓦，约占全国水电 16%，是全球最大的水电上市公司；毛利率与 ROE 稳居同业之首（竞争对手）。', '稀缺资产不等于定价权：电价由政府核定或随受电省份市场走（V5、V9）；来水决定年度波动（论证见 T1、T2）。', '不可复制：坝址唯一；新建同等规模的水电造价高得多、要十年以上（V7）。对照对手：华能水电、国投电力（雅砻江水电）、中国雅江集团（雅下水电）。', '气候变化与连续枯水；核定电价下调或税费提高；机组更新改造的资本开支。', '毛利率', '<', 0.5, 2),
((SELECT id FROM vi_company_base WHERE code = '600900.SH'), 'M2', '零燃料成本与折旧到期后的成本优势', '成本优势', '真实壁垒', '强', '增强', '水电没有燃料成本，成本约八成是折旧与利息这类固定成本；机组折旧到期、债务偿还后，同一座电站的度电成本继续下降，电站仍在发电。', '度电归母净利约 0.112 元、折旧约 0.064 元/千瓦时（2025 年）；财务费用 2023—2025 年 125.56 → 93.71 亿元；经营现金流是归母净利的 1.76 倍。', '三峡右岸机组 2025—2026 年、地下机组 2029—2030 年折旧到期，之后溪洛渡、向家坝接续（事实摘录）。', '折旧到期提升利润但不等额增加现金（还要更新改造，J-DA）；新项目会重新抬高折旧与利息（论证见 T4）。', '对手无法复制已建成、已折旧的资产成本；新建电站的度电成本远高于存量电站。对照对手：受电省份的煤电与新能源。', '更新改造与扩机的资本开支；抽蓄、新能源等新项目的折旧与利息。', NULL, NULL, NULL, NULL),
((SELECT id FROM vi_company_base WHERE code = '600900.SH'), 'M3', '六库联合调度', '工艺与组织', '局部优势', '中', '增强', '同一条江上的六座水库由一家公司统一调度：上游水库蓄放水服务下游电站，减少弃水、抬高水头，同样的来水多发电（“一滴水发六次电”）。', '2025 年节水增发电量 140.1 亿千瓦时（按 0.28 元/千瓦时约合 39 亿元收入），水能利用提高率 4.68%；年际发电量波动明显降低。', '2026 年上半年三峡来水偏丰、乌东德偏枯，合计发电量仍 +4.81%。', '联合调度只能熨平、不能创造来水：2026 年三季度发电量仍 −14.89%；防洪、航运优先时调度空间受限（论证见 T2）。', '只有拥有整条梯级的公司才能做；其他流域的公司（雅砻江、澜沧江）在自己的流域里也在做。对照对手：华能水电。', '长江委统一调度与防洪要求；上游其他公司水库的调度不受公司控制。', NULL, NULL, NULL, NULL),
((SELECT id FROM vi_company_base WHERE code = '600900.SH'), 'M4', '央企信用与低成本融资', '规模经济', '局部优势', '中', '稳定', '稳定的现金流与央企信用让公司能以接近国债的利率借钱，低息置换存量债务，降低资本成本，新项目的回报门槛也更低。', '财务费用 2023—2025 年下降 31.85 亿元（125.56 → 93.71），2025 年同比 −17.60 亿元。', '新发中票、超短融的票面利率约 1.3%—2.1%，低于存量债务成本（事实摘录）。', '大型央企都有相近的融资成本，不是公司独有的优势；利率上行时优势收窄（论证见 T4）。', '其他央企与地方能源国企都能拿到相近的利率。', '利率上行；信用政策收紧。', NULL, NULL, NULL, NULL),
((SELECT id FROM vi_company_base WHERE code = '600900.SH'), 'M5', '伪壁垒：管制电价与计划电量带来的“稳定”', '牌照与资源', '伪壁垒', '无', '削弱', '三峡、葛洲坝的电价由国家核定、不参与市场化交易，看起来是“受保护的价格”。', '—（电价稳定，但也封住了提价：2023—2025 年综合电价 0.2827 → 0.2856 → 0.2807 元）', '市场化电量占比从 2023 年以前的 15% 以下升到约 40%；乌东德、白鹤滩全部参与市场化交易。', '管制同时保护下行、封住上行；它是监管安排，可以被调整，不是公司自己建立的优势（论证见 T3）。', '—', '电力市场化改革继续推进，计划电量减少。', NULL, NULL, NULL, NULL),
((SELECT id FROM vi_company_base WHERE code = '600900.SH'), 'M6', '伪壁垒：“全球最大水电公司”的规模标签', '规模经济', '伪壁垒', '无', '稳定', '规模本身不带来定价权或更低的度电成本；真正的优势来自坝址资源（M1）和联合调度（M3），而不是“最大”。', '—', '雅砻江水电体量只有公司的三分之一左右，但利用小时更高（4,539 小时）；桂冠电力 ROE 也能到 15.8%。', '规模让联合调度和低成本融资更容易（已计入 M3、M4）。', '—', '—', NULL, NULL, NULL, NULL),
((SELECT id FROM vi_company_base WHERE code = '600900.SH'), 'M7', '伪壁垒：控股股东三峡集团的资产注入', '生态与渠道', '伪壁垒', '无', '削弱', '控股股东建好电站再注入公司（B6），看起来是“取之不尽的增长来源”。', '—（注入按评估价，用公司的股本和借款支付，回报取决于收购价格，不是竞争优势）', '2023 年收购乌东德、白鹤滩后，当年净借款 +295 亿元，财务费用随之升到 125.56 亿元；长江干流已没有大型待注入电站。', '若关联交易定价对少数股东有利，注入也能创造价值；集团 2026 年增持 44.99 亿元，利益基本一致。', '—', '关联交易定价。', NULL, NULL, NULL, NULL),
((SELECT id FROM vi_company_base WHERE code = '600900.SH'), 'M8', '抽水蓄能的资源储备与先发优势', '牌照与资源', '待验证', '弱', '增强', '锁定抽蓄资源近 4000 万千瓦、在建约 800—900 万千瓦，借助大水电的建设与运营经验进入新的调节资源赛道。', '容量电价按经营期定价法核定，资本金内部收益率约 6.5%；已在运的南网储能 ROE 约 7.5%。', '2025 年完成河南巩义、江西寻乌投资决策，收购河北青龙等 4 个项目公司；受托运维长龙山抽蓄（210 万千瓦）。', '抽蓄是“受管制的合理回报”，不是超额回报，规模越大整体 ROE 越被摊薄（论证见 T6）。', '南网储能、国网新源都在大规模建设；项目资源由地方政府配置，谁都能拿。', '容量电价政策调整；建设超支与延期。', NULL, NULL, NULL, NULL);
INSERT INTO vi_lnk_moat_facts (moat_id, fact_id, "createdAt", "updatedAt")
INSERT INTO vi_lnk_moat_theses (moat_id, thesis_id, "createdAt", "updatedAt")
INSERT INTO vi_fit_score_base (company_id, dimension, score, rationale, counter, sort) VALUES
((SELECT id FROM vi_company_base WHERE code = '600900.SH'), '长坡', 5, '电力需求长期稳定，清洁电力受青睐；但装机基本到顶，增长只能来自扩机、抽蓄与成本退坡（EPS 年化约 3%—4%）。', '沿海省份电力供需宽松；抽蓄与新能源的回报率低。', 1),
((SELECT id FROM vi_company_base WHERE code = '600900.SH'), '厚雪', 4, '境内水电毛利率 65.8%、ROE 约 16%，没有燃料成本，利润池厚且稳定。', '回报受监管上限约束，电价不是自己定；ROE 部分来自杠杆。', 2),
((SELECT id FROM vi_company_base WHERE code = '600900.SH'), '慢变', 4, '水电站寿命以百年计，电价机制、电网结构和用电需求变化都慢，未来十年的现金流可以合理估计。', '来水年际波动约 ±10%；电力市场化在加速（市场化电量已约 40%）；气候变化的长期影响未知。', 3),
((SELECT id FROM vi_company_base WHERE code = '600900.SH'), '护城河', 4, '长江干流坝址独占、零燃料成本与折旧到期的成本优势是真实壁垒（强）；联合调度、低息融资是局部优势。', '壁垒保护的是成本与稳定，不是定价权；管制电价、规模标签、集团注入是伪壁垒。', 4),
((SELECT id FROM vi_company_base WHERE code = '600900.SH'), '再投资', 4, '扩机增容边际成本极低；对外投资贡献稳定收益。', '大规模再投资（抽蓄、航运扩能）只有受管制的合理回报（资本金约 6.5%），新增资本难以获得存量电站的回报；历史增长靠控股股东注入。', 5),
((SELECT id FROM vi_company_base WHERE code = '600900.SH'), '财务质量', 4, '经营现金流是归母净利的 1.76 倍，披露完整；带息负债持续下降，财务费用逐年减少。', '带息负债仍约 2,900 亿元；投资收益约占利润七分之一，现金只分回约一半；2025 年四季度有约 10 亿元非经常性收益。', 6),
((SELECT id FROM vi_company_base WHERE code = '600900.SH'), '治理配置', 4, '分红承诺写入章程且长期兑现，近五年派息率均在 70% 以上；控股股东增持。', '资产注入、航运扩能等由集团主导的项目要看关联定价；央企承担的航运、防洪等社会功能可能让公司承担额外开支。', 7),
((SELECT id FROM vi_company_base WHERE code = '600900.SH'), '可估值性', 5, '收入＝电量×电价，两个变量都可长期跟踪；成本主要是折旧和利息，现金流可预测，适合把股息当票息算隐含回报。', '回报主要来自长期稳定的股息，终值占买入价约七成，对永续增长和长期电价很敏感（永续增长 ±1 个百分点，隐含回报约 ±0.7 个百分点）；来水让年度利润波动。', 8);
